function _pickWeighted(pool, seedInt){
  const total = pool.reduce((a,x)=>a + (x.w||0), 0) || 1;
  let r = (seedInt % total + total) % total;
  for(const it of pool){
    r -= (it.w||0);
    if(r <= 0) return it.name;
  }
  return pool[pool.length-1]?.name || "â€”";
}

function _geoBase(fn){
  const s = String(fn||"");
  const parts = s.split('/');
  return (parts[parts.length-1] || s);
}

function isOrchardGeoFile(fn){
  const s = _geoBase(fn).toLowerCase();
  return s.includes("bahce") || s.includes("bahce");
}

