function getVillageShare(village, cropNorm){
  const key = (village||"").toString().toUpperCase().replaceAll("Ä°","I").replaceAll("Å","S").replaceAll("Ä","G").replaceAll("Ãœ","U").replaceAll("Ã–","O").replaceAll("Ã‡","C");
  const v = STATE.villagePatterns?.[key] || STATE.villagePatterns?.[(village||"").toUpperCase()] || null;
  if(!v) return 0;
  const found = (v.top_crops||[]).find(x=>x.crop===cropNorm);
  return found ? +found.share : 0;
}

function getDistrictShare(district, cropNorm){
  const dKey = (district||"").toString().toUpperCase().replaceAll("Ä°","I").replaceAll("Å","S").replaceAll("Ä","G").replaceAll("Ãœ","U").replaceAll("Ã–","O").replaceAll("Ã‡","C");
  const d = STATE.districtPatterns?.[dKey] || STATE.districtPatterns?.[(district||"").toUpperCase()] || null;
  if(!d) return 0;
  const found = (d.top_crops||[]).find(x=>x.crop===cropNorm);
  return found ? +found.share : 0;
}

function normalizeVillageKey(v){
  return String(v||"").toUpperCase()
    .replaceAll("Ä°","I").replaceAll("IÌ‡","I")
    .replaceAll("Å","S").replaceAll("Ä","G").replaceAll("Ãœ","U")
    .replaceAll("Ã–","O").replaceAll("Ã‡","C")
    .trim();
}

function getParcelQuotaM3(parcelLike){
  const p = (typeof parcelLike === "object" && parcelLike) ? parcelLike : (parcelData||[]).find(x=>String(x?.id)===String(parcelLike));
  if(!p) return 0;
  const direct = safeNum(p.quota_m3 || p.parcel_quota_m3 || p.current_quota_m3, 0);
  if(direct > 0) return direct;
  const pid = String(p.id || p.parcel_id || "").trim();
  if(pid && STATE.parcelQuotaMap && safeNum(STATE.parcelQuotaMap[pid],0) > 0) return safeNum(STATE.parcelQuotaMap[pid],0);
  const vKey = normalizeVillageKey(p.village || p.koy || "");
  if(vKey && STATE.villageQuotaMap && safeNum(STATE.villageQuotaMap[vKey],0) > 0) return safeNum(STATE.villageQuotaMap[vKey],0);
  return 0;
}

function totalOfficialAreaDa(){
  const rows = Array.isArray(parcelData) && parcelData.length ? parcelData : (STATE.parcels || []);
  const sum = rows.reduce((a,p)=>{
    const water = safeNum(p.water_m3 ?? p.mevcut_su_m3 ?? p.water_m3_current, 0);
    const profit = safeNum(p.profit_tl ?? p.mevcut_kar_tl ?? p.profit_tl_current, 0);
    if(water <= 0 && profit <= 0) return a;
    return a + safeNum(p.area_official_da || p.official_area_da || p.area_da || p.area, 0);
  }, 0);
  return sum > 0 ? sum : Math.max(1, STATE.totalAreaAllParcels || 1);
}

function totalCurrentWaterM3(){
  const rows = Array.isArray(parcelData) && parcelData.length ? parcelData : (STATE.parcels || []);
  const sum = rows.reduce((a,p)=>a + Math.max(0, safeNum(p.water_m3 ?? p.mevcut_su_m3 ?? p.water_m3_current, 0)), 0);
  return sum > 0 ? sum : totalOfficialAreaDa() * 600;
}

function contextBonusTlPerDa(parcel, cropNorm){
  // kÃ¶y + ilÃ§e ekim desenine yakÄ±nsa kÃ¼Ã§Ã¼k bir bonus (TL/da)
  const v = getVillageShare(parcel.village, cropNorm);
  const d = getDistrictShare(parcel.district, cropNorm);
  const mix = (0.65*v + 0.35*d); // [0,1]
  return 1200 * mix; // demo Ã¶lÃ§eÄŸi
}

function parcelWaterBudget(areaDa, parcelLike=null){
  const model = String(STATE.waterAllocationModel || 'area_fair_per_da');
  const p = (typeof parcelLike === "object" && parcelLike) ? parcelLike : (parcelData||[]).find(x=>String(x?.id)===String(parcelLike));
  const area = Math.max(0, safeNum(areaDa || p?.area_official_da || p?.official_area_da || p?.area_da || p?.area, 0));
  const totalA = Math.max(1, totalOfficialAreaDa());
  const baseGlobal = computeGlobalBudgetM3();
  const areaFair = area > 0 ? (baseGlobal * (area / totalA)) : 0;
  const currentDemand = safeNum(p?.water_m3 ?? p?.mevcut_su_m3 ?? p?.water_m3_current, 0);
  if(model === 'current_demand_reference' && currentDemand > 0) return currentDemand;
  if(model === 'hybrid_area70_current30' && currentDemand > 0) return areaFair * 0.70 + currentDemand * 0.30;
  if(model === 'equal_village_equal_parcel'){
    const exactQuota = getParcelQuotaM3(p || parcelLike || null);
    if(isFinite(exactQuota) && exactQuota > 0) return exactQuota;
  }
  return areaFair;
}

function enforceParcelQuotaOnRows(rows, parcel){
  const out = deepCloneRows(Array.isArray(rows) ? rows : []);
  if(!parcel || !out.length || typeof parcelWaterBudget !== 'function') return out;
  const quota = parcelWaterBudget(safeNum(parcel.area_da || parcel.area_official_da || parcel.area, 0), parcel);
  const totals = sumMetrics(out);
  if(!(quota > 0) || !(safeNum(totals.water,0) > quota + 1e-6)) return out;
  const k = quota / Math.max(1, safeNum(totals.water,0));
  out.forEach(r=>{
    const oldArea = safeNum(r.area,0);
    const oldWater = safeNum(r.totalWater, oldArea * safeNum(r.waterPerDa,0));
    const oldProfit = safeNum(r.totalProfit, oldArea * safeNum(r.profitPerDa,0));
    r.area = oldArea * k;
    r.totalWater = oldWater * k;
    r.totalProfit = oldProfit * k;
    r.quotaLimited = true;
    r.decisionNote = [r.decisionNote, 'Alan bazlÄ± su kotasÄ± nedeniyle ekim alanÄ± kota kadar sÄ±nÄ±rlandÄ±.'].filter(Boolean).join(' ');
  });
  return out;
}

async function initWaterSelectors(){
  const yearSel = document.getElementById("waterYear");
  if(!yearSel) return;

  // Try backend years first
  let years=null; let defY=null;
  try{
    const r = await fetch('/api/years');
    const j = await r.json();
    if(j && j.years && j.years.length){ years = j.years; defY = j.default; }
  }catch(_){}

  // If backend provides no years, derive from active enhanced seasons (preferred)
  if(!years || !years.length){
    years = getAvailableYearsFromActiveSeasons();
    if(!years || !years.length){
      years = [];
      years = [2024];
    }
    defY = STATE.selectedWaterYear || (years.length ? years[years.length-1] : 2024);
  }

  // Set default
  if(!STATE.selectedWaterYear) STATE.selectedWaterYear = defY || years[years.length-1];

  // Fill options
  yearSel.innerHTML = "";
  for(const y of years){
    const opt=document.createElement("option");
    opt.value=String(y); opt.textContent=String(y);
    if(Number(y)===Number(STATE.selectedWaterYear)) opt.selected=true;
    yearSel.appendChild(opt);
  }

  const _handleWaterYearChange = ()=>{
    STATE.selectedWaterYear = Number(yearSel.value);

    // Rebuild year-dependent baselines and clear optimization caches
    // so recommendations can change across parcels/years.
    applyYearBaselinesFromSeasons();
    for(const k of Object.keys(basinPlanCache)) delete basinPlanCache[k];
    for(const k of Object.keys(optimizationCache)) delete optimizationCache[k];

    applyWaterScenarioFromUI();
    refreshTimeSeriesFromBackend();
    // refresh projection/time series charts
    refreshTimeSeriesFromBackend();
  };

  yearSel.addEventListener('change', _handleWaterYearChange);
  // Some browsers/UIs trigger 'input' more reliably for select changes; keep both.
  yearSel.addEventListener('input', _handleWaterYearChange);


  const scenSel = document.getElementById("waterScenarioSel");
  if(scenSel){
    scenSel.value = STATE.selectedProjScenario;
    scenSel.onchange=()=>{ STATE.selectedProjScenario=scenSel.value; applyWaterScenarioFromUI(true); };
  }
}


function computeDroughtRiskForYear(yil, dolulukIdx){
  // Basit risk: doluluk dÃ¼ÅŸÃ¼kse + trend kÃ¶tÃ¼leÅŸiyorsa artar (0-1)
  const idx = isFinite(dolulukIdx) ? dolulukIdx : 60;
  const low = clamp((35 - idx)/35, 0, 1); // 35 altÄ± hÄ±zlÄ± artar
  const slope = STATE._dolulukSlope10y ?? 0; // negatifse kÃ¶tÃ¼
  const trend = clamp((-slope)/4.0, 0, 1);   // ~-4 puan/yÄ±l ve altÄ± yÃ¼ksek risk
  const vol = clamp((STATE._dolulukStd10y ?? 0)/15.0, 0, 1);
  const sust = (STATE.sustainabilityIndex==null) ? 0.25 : clamp(1 - STATE.sustainabilityIndex, 0, 1);
  return clamp(0.45*low + 0.25*trend + 0.15*vol + 0.15*sust, 0, 1);
}

function updateDroughtAnalytics(){
  // If Chart.js not ready yet, retry shortly
  if(typeof Chart === "undefined"){
    setTimeout(()=>{ try{ updateDroughtAnalytics(); }catch(_e){} }, 250);
    return;
  }

  // barajRawSeries veya barajSeries Ã¼zerinden son 10 yÄ±llÄ±k trend/oynaklÄ±k Ã§Ä±kar
  const src = (STATE.barajRawSeries && STATE.barajRawSeries.length) ? STATE.barajRawSeries : STATE.barajSeries;
  if(!src || src.length < 5) return;

  const last = src.slice(-10);
  const ys = last.map(r=>r.yil);
  const xs = last.map(r=>r.doluluk);

  // linear regression slope
  const n = xs.length;
  const xbar = ys.reduce((a,b)=>a+b,0)/n;
  const ybar = xs.reduce((a,b)=>a+b,0)/n;
  let num=0, den=0;
  for(let i=0;i<n;i++){
    num += (ys[i]-xbar)*(xs[i]-ybar);
    den += (ys[i]-xbar)*(ys[i]-xbar);
  }
  const slope = den ? (num/den) : 0;
  STATE._dolulukSlope10y = slope;

  const mean = ybar;
  const varr = xs.reduce((a,v)=>a+(v-mean)*(v-mean),0)/Math.max(1,n-1);
  STATE._dolulukStd10y = Math.sqrt(varr);

  // sustainability: inflow/outflow dengesine gÃ¶re
  const inflow = last.map(r=>+r.girisim_hm3).filter(isFinite);
  const outflow = last.map(r=>+r.cekis_hm3).filter(isFinite);
  if(inflow.length && outflow.length){
    const inMean = inflow.reduce((a,b)=>a+b,0)/inflow.length;
    const outMean = outflow.reduce((a,b)=>a+b,0)/outflow.length;
    STATE.sustainabilityIndex = clamp((inMean - outMean) / Math.max(1e-6, inMean), -1, 1); // negatifse Ã§ekiÅŸ > giriÅŸ
    // 0-1 bandÄ±na indir
    STATE.sustainabilityIndex = clamp((STATE.sustainabilityIndex + 1)/2, 0, 1);
  }
}

function getHistMaxYear(){
  const ys = (STATE.barajSeries||[]).map(r=>+r.yil).filter(v=>isFinite(v));
  return ys.length ? Math.max(...ys) : 2024;
}

