      peakMonth:`${(typeof cropPeakMonthLabel === 'function') ? cropPeakMonthLabel(mix.a) : ''} / ${(typeof cropPeakMonthLabel === 'function') ? cropPeakMonthLabel(mix.b) : ''}`,
