          p.climate = p.climate || {};
          p.climate.eto_mm = Math.round(agg.eto_mm);
          p.climate.rain_mm = Math.round(agg.rain_mm);
          if(isFinite(agg.t_avg)) p.climate.t_avg = +agg.t_avg.toFixed(1);
          STATE.weatherSource = "offline";
