        if(weatherStatus) weatherStatus.textContent = "YÃ¼kleniyor...";
        const lat = parseNumFlex(weatherLat?.value, DEFAULT_COORDS.lat);
        const lon = parseNumFlex(weatherLon?.value, DEFAULT_COORDS.lon);
