function deepCloneRows(rows){
  return rows.map(r=>({
    name: r.name,
    season: r.season,
    area: +r.area,
    _baseWaterPerDa: +(r._baseWaterPerDa ?? r.baseWaterPerDa ?? r.waterPerDa ?? 0),
    waterPerDa: +r.waterPerDa,
    profitPerDa: +r.profitPerDa,
    totalWater: +r.totalWater,
    totalProfit: +r.totalProfit,
    irrigationCurrentKey: r.irrigationCurrentKey || null,
    irrigationCurrentText: r.irrigationCurrentText || null,
    irrigationSuggestedKey: r.irrigationSuggestedKey || null,
    irrigationSuggestedText: r.irrigationSuggestedText || r.irrigationSuggested || null,
    irrigationSuggested: r.irrigationSuggested || r.irrigationSuggestedText || null
  }));
}

function recomputeRowTotals(rows){
  for(const r of rows){
    r.totalWater = r.area * r.waterPerDa;
    r.totalProfit = r.area * r.profitPerDa;
  }
  return rows;
}

