function summarizeBenchmarkForSweepV95(j){
  const algos = j?.algorithms || {};
  const rows = Object.keys(algos);
  const out = {repeat:Number(j?.repeats||0), best:'-', avgCv:0, avgPlan:0, avgRuntime:0, feasible:0, note:''};
  if(!rows.length) return out;
  const objectiveRaw = String(j?.objective || j?.scenario || '').toLowerCase();
  const isWater = objectiveRaw.includes('water') || objectiveRaw.includes('su');
  const isProfit = objectiveRaw.includes('profit') || objectiveRaw.includes('kar');
  const rel = (m,s)=> (Math.abs(m) > 1e-9 ? Math.abs(s)/Math.abs(m) : 0);
  const scored = rows.map(a=>{
    const r = algos[a] || {};
    const pm = Number(r?.profit?.mean||0), ps = Number(r?.profit?.std||0);
    const wm = Number(r?.water?.mean||0), ws = Number(r?.water?.std||0);
    const em = Number(r?.efficiency?.mean||0), es = Number(r?.efficiency?.std||0);
    const cv = (rel(pm,ps)+rel(wm,ws)+rel(em,es))/3;
    const feasible = Number(r.feasible_rate||0);
    const runtime = Number(r?.runtime_s?.mean||0);
    const diversity = Number(r.unique_patterns||0);
    let core = em;
    if(isWater && !isProfit) core = (em * 1000) - (0.0002 * wm);
    else if(isProfit && !isWater) core = pm - (0.015 * wm);
    return {a, cv, feasible, runtime, diversity, score: core + feasible*0.25 + Math.min(0.05, diversity*0.01) - cv*0.4 - runtime*0.01};
  }).sort((x,y)=>y.score-x.score);
  const topScore = Number(scored[0]?.score || 0);
  const tied = scored.filter(x=> Math.abs(Number(x.score||0) - topScore) <= Math.max(1e-9, Math.abs(topScore) * 0.001));
  out.best = (tied.length > 1 ? tied.slice().sort((x,y)=>Number(x.runtime||0)-Number(y.runtime||0))[0]?.a : scored[0]?.a) || rows[0];
  out.avgCv = scored.reduce((s,x)=>s+x.cv,0)/Math.max(1,scored.length);
  out.avgRuntime = scored.reduce((s,x)=>s+x.runtime,0)/Math.max(1,scored.length);
  out.feasible = scored.reduce((s,x)=>s+x.feasible,0)/Math.max(1,scored.length);
  out.avgPlan = rows.reduce((s,a)=>s+Number(algos[a]?.plan_distance_pct?.mean||0),0)/Math.max(1,rows.length);
  const allSame = out.avgPlan < 0.5 && rows.every(a=>Number(algos[a]?.unique_patterns||0) <= 1);
  out.note = allSame
    ? 'Ayni optimuma yakinsiyor; veri/kisit havuzu dar oldugu icin ayni desen beklenebilir.'
    : (out.avgCv < 0.03 && out.avgPlan < 5 ? 'Stabil; tekrar artisi sonucu az degistiriyor.' : (out.avgCv < 0.08 ? 'Kabul edilebilir; tez tablosunda raporlanabilir.' : 'Oynaklik yuksek; 100 tekrar veya veri/kisit kontrolu onerilir.'));
  return out;
}

function renderBenchmarkSweepResultsV95(items){
  const box = document.getElementById('benchmarkSweepResults');
  if(!box) return;
  const rows = (items||[]).map(x=> x.summary).filter(Boolean);
  if(!rows.length){ box.innerHTML = ''; return; }
  const recommended = rows.find(r=> r.repeat >= 50 && r.avgCv < 0.08) || rows[rows.length-1];
  const detailRows = [];
  (items||[]).forEach(item=>{
    const repeat = Number(item?.repeat || item?.summary?.repeat || 0);
    const algos = item?.raw?.algorithms || {};
    Object.keys(algos).forEach(a=>{
      const r = algos[a] || {};
      detailRows.push({
        repeat,
        algo:a,
        profit:Number(r?.profit?.mean||0),
        water:Number(r?.water?.mean||0),
        eff:Number(r?.efficiency?.mean||0),
        cv:Number(r?.profit?.cv||0),
        plan:Number(r?.plan_distance_pct?.mean||0),
        feasible:Number(r?.feasible_rate||0),
        runtime:Number(r?.runtime_s?.mean||0),
        patterns:Number(r?.unique_patterns||0),
      });
    });
  });
  box.innerHTML = `<div class="benchmark-sweep-v95">
    <div class="matrix-title">Tekrar sayisi stabilite taramasi (30/50/100)</div>
    <table><thead><tr><th>Tekrar</th><th>Onerilen algoritma</th><th>Ortalama CV</th><th>Plan farki</th><th>Uygulanabilirlik</th><th>Ortalama sure</th><th>Akademik yorum</th></tr></thead><tbody>
      ${rows.map(r=>`<tr><td><b>${r.repeat}</b></td><td>${escapeHtml(r.best)}</td><td>${(r.avgCv*100).toFixed(2)}%</td><td>${r.avgPlan.toFixed(1)}%</td><td>${(r.feasible*100).toFixed(1)}%</td><td>${r.avgRuntime.toFixed(2)} sn</td><td>${escapeHtml(r.note)}</td></tr>`).join('')}
    </tbody></table>
    <p><b>Grafik okuma notu:</b> 30/50/100 grafiklerinde kar, su uygunlugu, TL/m3 ve sure her tekrar icinde 0-100 normalize skor olarak cizilir. Bu nedenle farkli tekrar kapsamlarinin ham buyuklukleri grafigi bozmaz; ham degerler asagidaki akademik tabloda okunur.</p>
    <div class="benchmark-detail-table-v97">
      <div class="matrix-title">Algoritma x tekrar ayrintili istatistik</div>
      <table><thead><tr><th>Tekrar</th><th>Algoritma</th><th>Kar ort</th><th>Su ort</th><th>TL/m3</th><th>Kar CV</th><th>Plan farki</th><th>Uygulanabilir</th><th>Sure</th><th>Desen</th></tr></thead><tbody>
        ${detailRows.map(r=>`<tr><td>${r.repeat}</td><td><b>${escapeHtml(r.algo)}</b></td><td>${fmtNum(r.profit,0)}</td><td>${fmtNum(r.water,0)}</td><td>${fmtNum(r.eff,2)}</td><td>${(r.cv*100).toFixed(2)}%</td><td>${fmtNum(r.plan,1)}%</td><td>${(r.feasible*100).toFixed(1)}%</td><td>${fmtNum(r.runtime,2)} sn</td><td>${fmtNum(r.patterns,0)}</td></tr>`).join('')}
      </tbody></table>
    </div>
    <p><b>Secilen tekrar politikasi:</b> ${recommended.repeat} tekrar. CV, plan farki ve uygulanabilirlik birlikte okunur; dusuk CV + dusuk plan farki overfitting degil, kisitlar altinda kararlÄ± yakÄ±nsama olarak yorumlanir.</p>
  </div>`;
}

async function runBenchmarkSweepV95(objective, seasonSource){
  const repeatsEl = document.getElementById('benchmarkRepeats');
  const oldVal = repeatsEl ? repeatsEl.value : '50';
  const counts = [30,50,100];
  const results = [];
  try{
    for(const count of counts){
      if(repeatsEl) repeatsEl.value = String(count);
      const j = await fetchBenchmarkPython(objective, seasonSource);
      if(benchmarkResultLooksBroken(j)) throw new Error(`${count} tekrar benchmark ciktisi bos veya hatali`);
      results.push({repeat:count, raw:j, summary:summarizeBenchmarkForSweepV95(j)});
      renderBenchmarkSweepResultsV95(results);
      updateBenchmarkSweepChartsV96(results);
    }
  }finally{
    if(repeatsEl) repeatsEl.value = oldVal;
  }
  return results;
}


// --- PYTHON BACKEND (Flask) ENTEGRASYONU ---
// Optimizasyon isteklerini /api/optimize Ã¼zerinden Python'a gÃ¶nderebilir.
// Bu sayede: (1) algoritmalar gerÃ§ekten Python'da Ã§alÄ±ÅŸÄ±r, (2) XLSX/JSON tÃ¼m desen verileri backend'de kullanÄ±lÄ±r.
async function fetchAndCacheBasinPlanPython(scenarioKey, algoKey){
  // âœ… Bu Ã§aÄŸrÄ± bu fonksiyonun "tek" optimize isteÄŸi olsun

  // 1) En baÅŸta reqId al
  const reqId = ++lastOptimizeReqId;

  // 2) Ã–nceki istekleri iptal ETME (stabilite iÃ§in)
  //    Eski sÃ¼rÃ¼m AbortController ile istekleri iptal ediyordu; bu Network'te (canceled) hatalarÄ±na yol aÃ§Ä±yordu.
  //    Bu sÃ¼rÃ¼mde iptal yok; reqId kontrolÃ¼ ile geÃ§ gelen sonuÃ§lar yok sayÄ±lÄ±r.


  const key = basinCacheKey(scenarioKey, algoKey);
  const algoMap = { ga: 'GA', abc: 'ABC', aco: 'ACO' };
  const scenarioMap = { mevcut: 'current', current: 'current', su_tasarruf: 'water_saving', 'su tasarruf':'water_saving', maks_kar: 'max_profit', 'maks kar':'max_profit', max_profit:'max_profit', onerilen: 'balanced', recommended: 'balanced', balanced:'balanced', water_efficiency:'balanced' };

  const payload = attachCustomParcelsToPayload({
    // v72: Run scope must match UI selection.
    // "__ALL__" -> basin totals, otherwise only the selected parcel.
    selectedParcelIds: getSelectedParcelIdsForRun(),
    algorithm: algoMap[algoKey] || 'GA',
    scenario: scenarioMap[scenarioKey] || 'recommended',
    waterBudgetRatio: budgetRatioForScenarioKey(scenarioKey),
    year: STATE.selectedWaterYear || null,
    options: {
      seasonSource: STATE.seasonSource || 's1',
      allocationModel: STATE.waterAllocationModel || 'area_fair_per_da',
      scenarioType: (((STATE.seasonSource || 's1')==='s2') ? 'double' : 'single'),
      twoSeason: ((STATE.seasonSource || 's1')==='s2'),
      maxCrops: 8,
      generations: 35,
      popSize: 40,
      iterations: 40,
      ants: 30,
      bees: 30,
      units: 20,
      // Deterministic seed helps reproducibility across runs.
      // Benchmark can override this.
      seed: 42,
      wWater: 1.0,
      wProfit: 1.0,
      wPattern: 0.4,
      simpleMode: false
    }
  });

  let res;
  try{
    res = await fetch("/api/optimize", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
});
  }catch(err){
    // abort ise sessiz Ã§Ä±k
    if (err && err.name === "AbortError") return null;
    throw err;
  }

  // 3) HTTP hata kontrolÃ¼
  if(!res.ok){
    const t = await res.text().catch(()=> "");
    throw new Error("Python optimize failed: " + (t || ("HTTP " + res.status)));
  }

  // 4) JSON'u SADECE 1 KERE oku
  const data = await res.json();

  // --- Normalize backend payload shapes ---
  // Backend can return either:
  // (A) {status:"OK", parcels:[{id, result:{recommended:[...]}}], ...}
  // (B) {algorithm, objective, water_budget_m3, details:[{parcelId, chosenCrop, area_da, water_m3, profit_tl}], ...}
  // We convert (B) into (A)-like structure so the UI logic stays consistent.
  let norm = data;
  if(norm && Array.isArray(norm.details) && !Array.isArray(norm.parcels)){
    const parcelsOut = [];
    for(const d of norm.details){
      const area = +d.area_da || 0;
      const pid = (d.parcelId || d.parcel_id || d.id || "").toString();

      // Two-season payload: {primary:{crop,water_m3,profit_tl}, secondary:{...}}
      if(d.primary && d.secondary){
        const w1 = +d.primary.water_m3 || 0;
        const p1 = +d.primary.profit_tl || 0;
        const w2 = +d.secondary.water_m3 || 0;
        const p2 = +d.secondary.profit_tl || 0;

        parcelsOut.push({
          id: pid,
          result: {
            recommended: [
              {
                name: prettyCropName(d.primary.crop || "URUN"),
                area,
                waterPerDa: area>0 ? (w1/area) : 0,
                profitPerDa: area>0 ? (p1/area) : 0
              },
              {
                name: prettyCropName(d.secondary.crop || "URUN"),
                area,
                waterPerDa: area>0 ? (w2/area) : 0,
                profitPerDa: area>0 ? (p2/area) : 0
              }
            ]
          }
        });
        continue;
      }

      // Single-crop payload
      const water = +d.water_m3 || 0;
      const profit = +d.profit_tl || 0;
      const name = (d.chosenCrop || d.chosen_crop || d.crop || "URUN").toString();
      parcelsOut.push({
        id: pid,
        result: {
          recommended: [{
            name,
            area,
            waterPerDa: area>0 ? (water/area) : 0,
            profitPerDa: area>0 ? (profit/area) : 0
          }]
        }
      });
    }
    norm = {
      status: "OK",
      parcels: parcelsOut,
      droughtFactor: norm.get ? undefined : norm.droughtFactor,
      water_budget_m3: norm.water_budget_m3,
      total_water_m3: norm.total_water_m3,
      total_profit_tl: norm.total_profit_tl,
      algorithm: norm.algorithm,
      objective: norm.objective,
      year: norm.year,
      meta: norm.meta
    };
  }

  // 5) EÄŸer bu cevap eski isteÄŸe aitse UI/cache gÃ¼ncelleme

  if (reqId !== lastOptimizeReqId) {
    console.warn("Eski optimize cevabÄ± yok sayÄ±ldÄ± (reqId mismatch)");
    return null;
  }

  // 6) Backend â€œOK deÄŸilâ€ diyorsa cacheâ€™e yazma
  if (norm.status && norm.status !== "OK") {
    alert("Optimizasyon reddedildi: " + (norm.reason || "BÃ¼tÃ§e aÅŸÄ±ldÄ±"));
    return null;
  }

  // 7) Python Ã§Ä±ktÄ±sÄ±nÄ± UIâ€™nin beklediÄŸi forma Ã§evir
  const plan = {};
  let totalWater = 0;
  let totalProfit = 0;

  for(const pr of (norm.parcels||[])){
    const parcelRef = (parcelData || []).find(p=>String(p.id)===String(pr.id)) || null;
    let rows = (pr.result?.recommended||[]).map(r=>{
      const area = +r.area || +r.area_da || 0;
      const waterPerDa = +r.waterPerDa || +r.water_m3_da || 0;
      const profitPerDa = +r.profitPerDa || +r.profit_tl_da || 0;
      const totalWater = area * waterPerDa;
      const totalProfit = area * profitPerDa;
      return {
        name: r.name,
        area,
        waterPerDa,
        profitPerDa,
        season: r.season || inferSeasonLabelFromCrop(r.name || '', pr.parcel_type || ''),
        decisionNote: r.decisionNote || '',
        reasonDetails: Array.isArray(r.reasonDetails) ? r.reasonDetails : [],
        cautionDetails: Array.isArray(r.cautionDetails) ? r.cautionDetails : [],
        compatibilityScore: safeNum(r.compatibilityScore, 0),
        irrigationCurrentKey: r.irrigationCurrentKey || r.irrigationCurrent || null,
        irrigationSuggestedKey: r.irrigationSuggestedKey || r.irrigationRecommended || null,
        unitType: r.unitType || null,
        unitsPerDaEst: +r.unitsPerDaEst || 0,
        estimatedUnitsTotal: +r.estimatedUnitsTotal || 0,
        estimatedYieldKg: +r.estimatedYieldKg || 0,
        grossRevenueTl: +r.grossRevenueTl || 0,
        estimatedCostTl: +r.estimatedCostTl || 0,
        estimatedNetProfitTl: +r.estimatedNetProfitTl || 0,
        waterEfficiencyTlPerM3: +r.waterEfficiencyTlPerM3 || 0,
        spacingNote: r.spacingNote || '',
        selectionBasis: r.selectionBasis || '',
        decisionGroup: r.decisionGroup || '',
        perennialLockRule: r.perennialLockRule || '',
        managementNote: r.managementNote || '',
        totalWater,
        totalProfit
      };
    });

    let totals = sumMetrics(rows);
    const quota = parcelRef && typeof parcelWaterBudget === 'function'
      ? parcelWaterBudget(safeNum(parcelRef.area_da, totals.area || 0), parcelRef)
      : 0;
    if(parcelRef && quota > 0 && safeNum(totals.water,0) > quota + 1e-6){
      const local = runOptimization(parcelRef, scenarioKey, algoKey);
      rows = deepCloneRows(local.rows || []);
      totals = sumMetrics(rows);
    }
    if(parcelRef){
      rows = enforceParcelQuotaOnRows(rows, parcelRef);
      totals = sumMetrics(rows);
    }
    plan[pr.id] = { rows, totals };
    totalWater += totals.water;
    totalProfit += totals.profit;
  }

  // UI'da bÃ¼tÃ§e tek kaynak olsun: 2024/mevcut desen toplam su varlÄ±ÄŸÄ±.
  // Backend bazÄ± kapsamlÄ± Ã§aÄŸrÄ±larda seÃ§ili parsel/kapsam bÃ¼tÃ§esi dÃ¶ndÃ¼rebiliyor;
  // rozet ve uygunluk hesabÄ±nda bunu "kÃ¼resel bÃ¼tÃ§e" gibi gÃ¶stermek hatalÄ± olur.
  const budget = computeGlobalBudgetM3();

  const out = {
    plan,
    budget,
    totals: { water: totalWater, profit: totalProfit, eff: totalProfit/Math.max(1,totalWater) },
    iterations: 0,
    feasible: totalWater <= budget + 1e-6,
    pythonMeta: norm.dataUsed || norm.meta || {},
    deliveryReport: (norm && norm.meta && (norm.meta.delivery_report || norm.meta.deliveryReport)) ? (norm.meta.delivery_report || norm.meta.deliveryReport) : null,
    droughtFactor: norm.droughtFactor,
    projection2050vs2025: norm.projection2050vs2025
  };

  // 8) Cacheâ€™e yaz (sadece son reqId iÃ§in)
  basinPlanCache[key] = out;

  return out;
}




// --- PYTHON BACKEND INTEGRATION ---
// When the Flask backend (app.py) is running, we can compute GA/ABC/ACO in Python and cache
// results into the existing basinPlanCache so the UI continues to work without rewriting.
async function fetchAndCacheBasinPlanFromServer(scenarioKey, algoKey){
  const key = basinCacheKey(scenarioKey, algoKey);
  const url = '/api/optimize';
  // Map UI keys to backend
  const algoMap = {ga:'GA', abc:'ABC', aco:'ACO'};
  const scenarioMap = { mevcut: 'current', current: 'current', su_tasarruf: 'water_saving', maks_kar: 'max_profit', max_profit:'max_profit', onerilen: 'balanced', recommended: 'balanced', balanced:'balanced', water_efficiency:'balanced' };
  const payload = attachCustomParcelsToPayload({
    selectedParcelIds: getSelectedParcelIdsForRun(),
    algorithm: algoMap[algoKey] || 'GA',
    scenario: scenarioMap[scenarioKey] || 'balanced',
    waterBudgetRatio: budgetRatioForScenarioKey(scenarioKey),
    options: {
      allocationModel: STATE.waterAllocationModel || 'area_fair_per_da',
      maxCrops: 8,
      // weights can be tuned from UI later
      wWater: 1.0,
      wProfit: 1.0,
      wPattern: 0.4,
      simpleMode: false
    }
  });

  const res = await fetch(url, {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(payload)
  });
  if(!res.ok){
    throw new Error('Python optimize API failed: '+res.status);
  }
  const data = await res.json();

  const plan = {};
  let totalWater = 0;
  let totalProfit = 0;

  // Normalize to expected shape
  const norm = data;
  for(const pr of (norm.parcels||[])){
    const rows = (pr.result?.recommended||[]).map(r=>({
      name: r.name,
      area: +r.area || +r.area_da || 0,
      waterPerDa: +r.waterPerDa || +r.water_m3_da || 0,
      profitPerDa: +r.profitPerDa || +r.profit_tl_da || 0,
      season: r.season || inferSeasonLabelFromCrop(r.name || '', pr.parcel_type || ''),
      decisionNote: r.decisionNote || '',
      reasonDetails: Array.isArray(r.reasonDetails) ? r.reasonDetails : [],
      cautionDetails: Array.isArray(r.cautionDetails) ? r.cautionDetails : [],
      compatibilityScore: safeNum(r.compatibilityScore, 0),
      totalWater: (+r.area || +r.area_da || 0) * (+r.waterPerDa || +r.water_m3_da || 0),
      totalProfit: (+r.area || +r.area_da || 0) * (+r.profitPerDa || +r.profit_tl_da || 0)
    }));
    const totals = sumMetrics(rows);
    plan[pr.id] = { rows: rows, totals: totals };
    totalWater += totals.water;
    totalProfit += totals.profit;
  }

  const out = {
    plan,
    budget: computeGlobalBudgetM3(),
    totals: { water: totalWater, profit: totalProfit, eff: totalProfit/Math.max(1,totalWater) },
    iterations: null,
    feasible: totalWater <= computeGlobalBudgetM3() + 1e-6,
    server: true,
    dataUsed: data.dataUsed
  };

  basinPlanCache[key] = out;
  return out;
}
