function inferParcelTypeKey(input){
  const raw = (typeof input === 'string') ? input : (input?.parcel_type || input?.land_type || input?.type || '');
  const key = String(raw || '').toLowerCase();
  if(key === 'orchard' || key === 'field' || key === 'vegetable') return key;
  const cropName = (typeof input === 'string')
    ? input
    : (input?.current_crop || input?.cropCurrent?.[0]?.name || input?.feature?.properties?.current_crop || input?.feature?.properties?.crop || '');
  const norm = normCropKey(cropName).replace(/\([^)]*\)/g, ' ');
  const orchardHints = ['ELMA','ARMUT','KIRAZ','VISNE','SEFTALI','NEKTAR','KAYISI','ERIK','CEVIZ','BAG','UZUM','BADEM','AYVA','DUT','ZERDALI','IGDE','CILEK'];
  const vegetableHints = ['DOMATES','BIBER','LAHANA','PATLICAN','ISPANAK','PIRASA','SOGAN','SARIMSAK','KABAK','KARPUZ','KAVUN','HIYAR','TURP','BAMYA','FASULYE_TAZE','BEZELYE'];
  if(orchardHints.some(k=>norm.includes(k))) return 'orchard';
  if(vegetableHints.some(k=>norm.includes(k))) return 'vegetable';
  return 'field';
}

