function centroidOfLatLngs(latlngs){
  const pts = (latlngs||[]).filter(p=>p && isFinite(+p.lat) && isFinite(+p.lng));
  if(!pts.length) return {lat:37.957776, lng:34.353984};
  const lat = pts.reduce((s,p)=>s+(+p.lat),0) / pts.length;
  const lng = pts.reduce((s,p)=>s+(+p.lng),0) / pts.length;
  return {lat, lng};
}

const EARTH_RADIUS_M = 6378137;

function ensureClosedLonLatRing(coords){
  const pts = (coords||[]).filter(c=>Array.isArray(c) && c.length >= 2 && isFinite(+c[0]) && isFinite(+c[1])).map(c=>[+c[0], +c[1]]);
  if(!pts.length) return [];
  const first = pts[0];
  const last = pts[pts.length - 1];
  if(first[0] !== last[0] || first[1] !== last[1]) pts.push([first[0], first[1]]);
  return pts;
}

function signedRingAreaSquareMetersLonLat(coords){
  const ring = ensureClosedLonLatRing(coords);
  if(ring.length < 4) return 0;
  let sum = 0;
  for(let i=0; i<ring.length-1; i++){
    const lon1 = ring[i][0] * Math.PI / 180;
    const lat1 = ring[i][1] * Math.PI / 180;
    const lon2 = ring[i+1][0] * Math.PI / 180;
    const lat2 = ring[i+1][1] * Math.PI / 180;
    sum += (lon2 - lon1) * (2 + Math.sin(lat1) + Math.sin(lat2));
  }
  return (sum * EARTH_RADIUS_M * EARTH_RADIUS_M) / 2;
}

function polygonAreaSquareMetersLonLat(rings){
  if(!Array.isArray(rings) || !rings.length) return 0;
  const outer = Math.abs(signedRingAreaSquareMetersLonLat(rings[0]));
  const holes = (rings.slice(1) || []).reduce((s, ring)=>s + Math.abs(signedRingAreaSquareMetersLonLat(ring)), 0);
  return Math.max(0, outer - holes);
}

function geometryAreaSquareMeters(geometry){
  const g = geometry || {};
  if(g.type === 'Polygon') return polygonAreaSquareMetersLonLat(g.coordinates || []);
  if(g.type === 'MultiPolygon') return (g.coordinates || []).reduce((s, poly)=>s + polygonAreaSquareMetersLonLat(poly || []), 0);
  return 0;
}

function featureAreaSquareMeters(feature){
  try{
    const areaM2 = geometryAreaSquareMeters(feature?.geometry);
    if(areaM2 > 0) return areaM2;
  }catch(_e){}
  try{
    const latlngs = latLngsFromFeature(feature);
    return areaSquareMetersFromLatLngs(latlngs);
  }catch(_e){}
  return 0;
}

function areaSquareMetersFromLatLngs(latlngs){
  const coords = (latlngs||[]).filter(p=>p && isFinite(+p.lat) && isFinite(+p.lng)).map(p=>[+p.lng, +p.lat]);
  return Math.max(0, polygonAreaSquareMetersLonLat([coords]));
}

function areaDaFromLatLngs(latlngs){
  const areaM2 = areaSquareMetersFromLatLngs(latlngs);
  return areaM2 > 0 ? areaM2 / 1000 : 0;
}

function currentGeometryAreaDa(parcel){
  if(!parcel) return 0;
  try{
    if(parcel.feature){
      const areaDa = featureAreaSquareMeters(parcel.feature) / 1000;
      if(areaDa > 0) return areaDa;
    }
  }catch(_e){}
  return safeNum(parcel.area_da, 0);
}

function isGeometryDrivenParcel(parcel){
  try{
    return !!(parcel && parcel.feature && currentGeometryAreaDa(parcel) > 0);
  }catch(_e){
    return false;
  }
}

function syncAreaInputMode(parcel){
  const areaEl = document.getElementById('manualParcelArea');
  const toggle = document.getElementById('manualAreaOverrideToggle');
  if(!areaEl) return;
  const geometryDriven = isGeometryDrivenParcel(parcel);
  const manualEnabled = !!(toggle && toggle.checked);
  areaEl.readOnly = geometryDriven && !manualEnabled;
  areaEl.title = geometryDriven && !manualEnabled
    ? 'Alan seÃ§ilen geometriye gÃ¶re otomatik hesaplanÄ±r.'
    : '';
}

function updateAreaInputFromGeometry(parcel, force=false){
  const areaEl = document.getElementById('manualParcelArea');
  const toggle = document.getElementById('manualAreaOverrideToggle');
  if(!areaEl || !parcel) return 0;
  const areaDa = currentGeometryAreaDa(parcel);
  const manualEnabled = !!(toggle && toggle.checked);
  if(areaDa > 0){
    parcel.area_da = +areaDa.toFixed(1);
    if(force || !manualEnabled || !safeNum(areaEl.value, 0)){
      areaEl.value = parcel.area_da.toFixed(1);
    }
  }
  syncAreaInputMode(parcel);
  return areaDa;
}

function latLngsFromFeature(feature){
  try{
    const lyr = L.geoJSON(feature);
    const out = [];
    const walk = (node)=>{
      if(!node) return;
      if(Array.isArray(node)){
        node.forEach(walk);
        return;
      }
      if(isFinite(+node.lat) && isFinite(+node.lng)) out.push(node);
    };
    lyr.eachLayer(l=>{
      if(typeof l.getLatLngs === 'function') walk(l.getLatLngs());
    });
    return out;
  }catch(_e){
    return [];
  }
}

function ensureCropSuggestions(){
  const dl = document.getElementById('cropSuggestions');
  if(!dl) return;
  const names = new Set();
  try{
    Object.keys(STATE?.cropCatalog || {}).forEach(k=>{
      const nm = STATE.cropCatalog[k]?.displayName || STATE.cropCatalog[k]?.name || prettyCropName(k);
      if(nm) names.add(String(nm));
    });
  }catch(_e){}
  try{
    Object.keys((typeof cropCatalog !== 'undefined' ? cropCatalog : {}) || {}).forEach(k=>{
      const nm = cropCatalog[k]?.displayName || cropCatalog[k]?.name || prettyCropName(k);
      if(nm) names.add(String(nm));
    });
  }catch(_e){}
  dl.innerHTML = Array.from(names).sort((a,b)=>a.localeCompare(b,'tr')).map(n=>`<option value="${escapeHtml(n)}"></option>`).join('');
}

function customParcelsForApi(){
  const currentUser = STATE.currentUser;
  return (parcelData || [])
    .filter(p => !!p?.frontend_custom || !!p?.frontend_override)
    .filter(p => {
      if(p?.frontend_override && !p?.frontend_custom) return true;
      const meta = customParcelApprovalMeta(p);
      const owner = String(p.owner_username || p.feature?.properties?.owner_username || '').trim();
      if(p.requested_for_parcel_id && p.promoted_to_official) return false;
      if(meta.status !== 'approved') return false;
      if(currentUser?.role === 'institution') return true;
      return !!currentUser && owner === currentUser.username;
    })
    .map(p=>({
      id: String(p.id),
      name: String(p.name || p.id),
      village: String(p.village || ''),
      district: String(p.district || ''),
      area_da: +safeNum(p.area_da, 0).toFixed(2),
      lat: +safeNum(p.lat, 0).toFixed(6),
      lon: +safeNum(p.lon, 0).toFixed(6),
      water_m3: +safeNum(p.water_m3, 0).toFixed(2),
      profit_tl: +safeNum(p.profit_tl, 0).toFixed(2),
      current_crop: String(p.current_crop || ''),
      irrigation_key: String(p.irrigation_key || ''),
      farmer: String(p.farmer || ''),
      parcel_type: String(p.parcel_type || ''),
      source_label: String(p.source_label || ''),
      owner_username: String(p.owner_username || p.feature?.properties?.owner_username || ''),
      approval_status: String(p.approval_status || (p.frontend_override ? 'approved' : 'approved')),
      requested_for_parcel_id: String(p.requested_for_parcel_id || ''),
      soil: p.soil || {},
    }));
}

function attachCustomParcelsToPayload(payload){
  const cps = customParcelsForApi();
  if(!cps.length) return payload;
  payload.customParcels = cps;
  payload.options = payload.options || {};
  payload.options.customParcels = cps;
  return payload;
}

