function estimateParcelBaselineFromForm(parcel, cropName, irrigationKey){
  const A = safeNum(parcel?.area_da, 0);
  const meta = cropMetaByName(cropName) || {};
  let waterPerDa = safeNum(meta.waterPerDa ?? meta.water_m3_da ?? meta.su_tuketimi_m3_da, NaN);
  let profitPerDa = safeNum(meta.profitPerDa ?? meta.net_kar_tl_da ?? meta.kar_tl_da, NaN);
  if(!isFinite(waterPerDa) || waterPerDa < 0){
    waterPerDa = (String(irrigationKey||'') === 'rainfed') ? 180 : 520;
  }
  if(!isFinite(profitPerDa) || profitPerDa < 0){
    profitPerDa = 4500;
  }
  if(String(irrigationKey||'') === 'rainfed') waterPerDa *= 0.45;
  if(String(irrigationKey||'') === 'drip') waterPerDa *= 0.85;
  if(String(irrigationKey||'') === 'pivot') waterPerDa *= 0.92;
  return {
    waterPerDa: +waterPerDa.toFixed(2),
    profitPerDa: +profitPerDa.toFixed(2),
    water_m3: +(A * waterPerDa).toFixed(1),
    profit_tl: +(A * profitPerDa).toFixed(1),
  };
}

function getBaseOfficialParcel(parcel){
  return (parcelData || []).find(x => String(x?.id) === String(parcel?.requested_for_parcel_id || '') && !x?.frontend_custom) || null;
}

function buildApproxFeatureForParcel(parcel){
  const lat = safeNum(parcel?.lat, 37.96);
  const lon = safeNum(parcel?.lon, 34.68);
  const d = 0.0008;
  return {
    type:'Feature',
    properties:{ id:String(parcel?.id || ''), name:String(parcel?.name || parcel?.id || '') },
    geometry:{ type:'Polygon', coordinates:[[
      [lon-d, lat-d], [lon+d, lat-d], [lon+d, lat+d], [lon-d, lat+d], [lon-d, lat-d]
    ]] }
  };
}

