// Mevcut / Ã¶nerilen tablolarÄ± doldur

// -------------------------
// Optimizasyon motoru (GA / ABC / ACO)
// AmaÃ§: senaryoya gÃ¶re (su_tasarruf / maks_kar) parsel alanÄ±nÄ± Ã¼rÃ¼nler arasÄ±nda paylaÅŸtÄ±rmak
// Not: Bu demo sÃ¼rÃ¼mÃ¼nde 8â€“11 Ã¼rÃ¼n arasÄ±ndan optimizasyon yapÄ±lÄ±r. Ä°leride gerÃ§ek Ã¼rÃ¼n-Ã§eÅŸit veri seti ile geniÅŸletilir.
// -------------------------

function clamp(v, a, b){ return Math.max(a, Math.min(b, v)); }

// TÃ¼rkÃ§e yerel ayarlarda ondalÄ±k ayÄ±rÄ±cÄ± virgÃ¼l olabildiÄŸi iÃ§in gÃ¼venli sayÄ± ayrÄ±ÅŸtÄ±rma
function parseNumFlex(v, fallback){
  if(v===undefined || v===null) return fallback;
  const s = String(v).trim().replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeVec(x){
  const s = x.reduce((acc,v)=>acc+Math.max(0,v),0);
  if(!s) return x.map(()=>1/x.length);
  return x.map(v=>Math.max(0,v)/s);
}

function vecToRows(areaDa, crops, x){
  // x: proportions
  const xN = normalizeVec(x);
  // area rounding
  let rows = crops.map((c,i)=>({
    name: c.name,
    area: +(areaDa * xN[i]).toFixed(1),
    waterPerDa: c.waterPerDa,
    profitPerDa: c.profitPerDa,
  }));
  // Fix rounding so sum equals areaDa
  const sumArea = rows.reduce((a,r)=>a+r.area,0);
  const diff = +(areaDa - sumArea).toFixed(1);
  if(Math.abs(diff) >= 0.1){
    // adjust largest area crop
    let j = 0;
    for(let i=1;i<rows.length;i++) if(rows[i].area > rows[j].area) j=i;
    rows[j].area = +(rows[j].area + diff).toFixed(1);
  }
  rows = rows.filter(r=>r.area > 0.0);
  rows.forEach(r=>{
    r.totalWater = r.area * r.waterPerDa;
    r.totalProfit = r.area * r.profitPerDa;
  });
  return rows;
}

function sumMetrics(rows){
  const totalArea = rows.reduce((a,r)=>a+r.area,0);
  const totalWater = rows.reduce((a,r)=>a+r.totalWater,0);
  const totalProfit = rows.reduce((a,r)=>a+r.totalProfit,0);
  return { area: totalArea, water: totalWater, profit: totalProfit, totalArea, totalWater, totalProfit };
}

// --- v54: Sulama randÄ±manÄ± (yÃ¶ntem bazlÄ±) ---
// Basit varsayÄ±mlar: yÃ¼zey/karÄ±k dÃ¼ÅŸÃ¼k, yaÄŸmurlama orta, damla yÃ¼ksek.
const IRR_EFF = { surface:0.55, sprinkler:0.70, drip:0.90, pivot:0.80, rainfed:1.00 };
function deliveredWaterPerDa(baseWaterPerDa, irrKey){
  // Koruma: Ã¶lÃ§ek hatasÄ±yla gelen aÅŸÄ±rÄ± bÃ¼yÃ¼k deÄŸerleri UI'da patlatma.
  const w = clamp(safeNum(baseWaterPerDa), 0, 3000);
  const k = irrKey || 'sprinkler';
  if(k === 'rainfed') return w * 0.20; // destek sulamasÄ± varsayÄ±mÄ±
  const eff = IRR_EFF[k] || (STATE.irrigEfficiency ?? 0.62);
  return w / Math.max(0.35, eff);
}

// Ã–neri sulama yÃ¶ntemi: karÄ±k/salma -> damla (sebzede), kuru tahÄ±l -> yaÄŸmurlama (destek),
// pivot/yaÄŸmurlama -> damla (yÃ¼ksek su tasarrufu hedefinde)
function recommendedIrrKeyForCrop(cropName, currentKey){
  const nm = (cropName||'').toLowerCase();
  if(currentKey === 'rainfed') return 'sprinkler';
  if(nm.includes('buÄŸday') || nm.includes('arpa') || nm.includes('Ã§avdar')) return currentKey === 'rainfed' ? 'sprinkler' : 'sprinkler';
  // sebze/endÃ¼stri bitkilerinde damla hedef
  if(currentKey === 'surface' || currentKey === 'sprinkler' || currentKey === 'pivot') return 'drip';
  return 'drip';
}

function irrigationLabel(key){
  if(key==='drip') return 'Damla';
  if(key==='sprinkler') return 'YaÄŸmurlama';
  if(key==='surface') return 'KarÄ±k/Salma';
  if(key==='pivot') return 'Pivot/Lineer';
  if(key==='rainfed') return 'YaÄŸÄ±ÅŸa baÄŸlÄ±';
  return String(key||'â€”');
}

function isBlankSeasonLabel(v){
  const s = String(v ?? '').trim().toLowerCase();
  return !s || s==='â€”' || s==='-' || s==='nan' || s==='undefined' || s==='null';
}

function getCropCatalogEntry(cropName){
  const key = normCropName(cropName || '');
  return (STATE.cropCatalog && STATE.cropCatalog[key]) ? STATE.cropCatalog[key] : null;
}

function irrigationMethodMeta(methodKey){
  const map = { surface:'surface_furrow', sprinkler:'sprinkler', drip:'drip', pivot:'sprinkler', rainfed:'surface_furrow' };
  const wanted = map[String(methodKey || '').trim()] || String(methodKey || '').trim();
  return (STATE.irrigMethods || []).find(r => String(r.method || '').trim() === wanted) || {
    method: wanted, capex_tl_per_da: 0, opex_tl_per_da: 0, typical_total_efficiency: IRR_EFF[methodKey] || 0.62
  };
}

function costBreakdownRuleFor(parcelType, category, cropName=''){
  const rows = Array.isArray(STATE.costBreakdownRules) ? STATE.costBreakdownRules : [];
  const pt = String(parcelType || '').trim().toLowerCase();
  const cat = String(category || '').trim().toLowerCase();
  const crop = String(cropName || '').trim().toLowerCase();
  let hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && String(r.crop || '').trim().toLowerCase() === crop && crop);
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && String(r.category || '').trim().toLowerCase() === cat && cat && !String(r.crop || '').trim());
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && !String(r.category || '').trim() && !String(r.crop || '').trim());
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === 'default');
  return hit || null;
}

function inferParcelTypeForUi(row, parcel){
  const cat = getCropCatalogEntry(row?.name || '');
  return String(cat?.parcelType || row?.parcelType || parcel?.parcel_type || '').trim().toLowerCase() || (isPerennialCropName(row?.name || '') ? 'orchard' : 'field');
}

function computeRowEconomics(row, parcel, methodKey, baselineMethodKey){
  const cat = getCropCatalogEntry(row?.name || '') || {};
  const area = safeNum(row?.area, 0);
  const baseWaterPerDa = safeNum(row?._baseWaterPerDa, 0) || safeNum(row?.waterPerDa, 0);
  const appliedMethod = methodKey || row?.irrigationSuggestedKey || row?.irrigationCurrentKey || irrigationKeysForCrop(row?.name || '').suggestedKey || 'sprinkler';
  const baselineMethod = baselineMethodKey || row?._baselineMethodKey || row?.irrigationSuggestedKey || row?.irrigationCurrentKey || appliedMethod;
  const methodMeta = irrigationMethodMeta(appliedMethod);
  const baselineMethodMeta = irrigationMethodMeta(baselineMethod);
  const waterPerDa = deliveredWaterPerDa(baseWaterPerDa, appliedMethod);
  const totalWater = area * waterPerDa;

  const priceTlKg = safeNum(cat.price_tl_kg ?? cat.priceTlPerKg, 0);
  const yieldKgDa = safeNum(cat.yield_kg_da ?? cat.yieldKgPerDa, 0);
  const supportTlDa = safeNum(cat.support_tl_da ?? cat.supportTlPerDa, 0);
  const hasMarketBasis = yieldKgDa > 0 && priceTlKg > 0;
  const grossDa = hasMarketBasis ? (safeNum(cat.grossRevenueTlPerDa, 0) || (yieldKgDa * priceTlKg)) : 0;
  const grossRevenue = hasMarketBasis ? (area * grossDa) : NaN;
  const baselineNet = safeNum(row?.totalProfit, 0) || (area * safeNum(row?.profitPerDa, 0));
  const baselineIrrigationOpexTotal = area * safeNum(baselineMethodMeta.opex_tl_per_da, 0);
  const irrigationOpexTotal = area * safeNum(methodMeta.opex_tl_per_da, 0);
  const targetNet = baselineNet - (irrigationOpexTotal - baselineIrrigationOpexTotal);
  const catalogTotalCost = area * safeNum(cat.cost_tl_da ?? cat.costTlPerDa ?? cat.var_cost_tl_da ?? cat.varCostTlPerDa, 0);
  let totalCost = NaN;
  if(hasMarketBasis){
    totalCost = Math.max(catalogTotalCost, grossRevenue + (area * supportTlDa) - targetNet);
    if(!isFinite(totalCost)) totalCost = catalogTotalCost || 0;
  }

  const remainingCost = hasMarketBasis ? Math.max(0, totalCost - irrigationOpexTotal) : 0;
  const parcelType = inferParcelTypeForUi(row, parcel);
  const rule = costBreakdownRuleFor(parcelType, cat.category || '', row?.name || '');
  const shares = rule || {};
  const defaultParts = [
    ['Tohum / fide / fidan', 0.14],
    ['GÃ¼bre', 0.18],
    ['Ä°laÃ§ / bitki koruma', 0.10],
    ['Toprak iÅŸleme', 0.14],
    ['Ä°ÅŸÃ§ilik / bakÄ±m', 0.20],
    ['Hasat / paketleme', 0.14],
    ['DiÄŸer', 0.10],
  ];
  const rawParts = [
    ['Tohum / fide / fidan', safeNum(shares.seed_fidan_share, 0.14)],
    ['GÃ¼bre', safeNum(shares.fertilizer_share, 0.18)],
    ['Ä°laÃ§ / bitki koruma', safeNum(shares.pesticide_share, 0.10)],
    ['Toprak iÅŸleme', safeNum(shares.tillage_share, 0.14)],
    ['Ä°ÅŸÃ§ilik / bakÄ±m', safeNum(shares.labor_maintenance_share, 0.20)],
    ['Hasat / paketleme', safeNum(shares.harvest_packaging_share, 0.14)],
    ['DiÄŸer', safeNum(shares.other_share, 0.10)],
  ];
  const rawShareSum = rawParts.reduce((s, x) => s + Math.max(0, safeNum(x[1], 0)), 0);
  const parts = rawShareSum > 1e-9 ? rawParts : defaultParts;
  const sumShare = Math.max(1e-9, parts.reduce((s, x) => s + x[1], 0));
  const breakdown = hasMarketBasis
    ? parts.map(([label, share]) => ({ label, amount: remainingCost * (share / sumShare) }))
    : [{ label:'Net kÃ¢r kaydÄ± / proxy', amount: targetNet }];
  breakdown.push({ label:'Sulama iÅŸletme', amount: irrigationOpexTotal });

  return {
    crop: prettyCropName(row?.name || 'â€”'),
    season: !isBlankSeasonLabel(row?.season) ? row.season : inferSeasonLabelFromCrop(row?.name || '', parcel?.parcel_type || ''),
    methodKey: appliedMethod,
    methodLabel: irrigationLabel(appliedMethod),
    areaDa: area,
    priceTlKg,
    yieldKgDa,
    totalProductionKg: area * yieldKgDa,
    grossRevenueTl: grossRevenue,
    totalCostTl: totalCost,
    totalNetProfitTl: targetNet,
    supportTotalTl: area * supportTlDa,
    waterPerDa,
    totalWaterM3: totalWater,
    waterCostTlPerM3: totalWater > 0 ? (irrigationOpexTotal / totalWater) : 0,
    tlPerM3: totalWater > 0 ? (targetNet / totalWater) : 0,
    breakdown,
    operationsNote: String(rule?.operations_note || '').trim(),
    parcelType,
    category: String(cat.category || '').trim(),
    capexTlPerDa: safeNum(methodMeta.capex_tl_per_da, 0),
    opexTlPerDa: safeNum(methodMeta.opex_tl_per_da, 0),
    dataNote: String(cat.sourceNote || '').trim(),
    hasMarketBasis,
    economicsNote: hasMarketBasis
      ? String(cat.sourceNote || '2024 fiyat/verim/gider kataloÄŸu').trim()
      : 'Bu Ã¼rÃ¼n iÃ§in 2024 fiyat-verim-gider satÄ±rÄ± bulunamadÄ±; net kÃ¢r Ã¶neri/desen satÄ±rÄ±ndaki TL/da deÄŸerinden proxy olarak gÃ¶sterildi.',
  };
}

function renderBusinessMetrics(currentRows, recRows, parcel, objectiveKey){
  const box = document.getElementById('businessMetricsBox');
  if(!box) return;
  const current = Array.isArray(currentRows) ? currentRows : [];
  const rec = Array.isArray(recRows) ? recRows : [];
  if(!current.length){
    box.innerHTML = '<div class="small muted">Ekonomik dayanak iÃ§in Ã¶nce parsel verisi yÃ¼klenmelidir.</div>';
    return;
  }

  const buildTable = (rows, title, mode)=>{
    const econRows = rows.map(r => computeRowEconomics(
      r,
      parcel,
      mode==='recommended' ? (r.irrigationSuggestedKey || irrigationKeysForCrop(r.name).suggestedKey) : (r.irrigationCurrentKey || irrigationKeysForCrop(r.name).currentKey),
      mode==='recommended' ? (r.irrigationSuggestedKey || irrigationKeysForCrop(r.name).suggestedKey) : (r.irrigationCurrentKey || irrigationKeysForCrop(r.name).currentKey)
    ));
    const totals = econRows.reduce((acc, r)=>{
      acc.area += r.areaDa;
      if(r.hasMarketBasis){
        acc.known += 1;
        acc.prod += safeNum(r.totalProductionKg, 0);
        acc.gross += safeNum(r.grossRevenueTl, 0);
        acc.cost += safeNum(r.totalCostTl, 0);
      }
      acc.net += safeNum(r.totalNetProfitTl, 0);
      acc.water += safeNum(r.totalWaterM3, 0);
      return acc;
    }, {area:0, prod:0, gross:0, cost:0, net:0, water:0, known:0});
    const lead = econRows[0] || null;
    const money = (v, known=true)=> known ? Math.round(safeNum(v,0)).toLocaleString('tr-TR') : '<span class="muted">Veri yok</span>';
    const num = (v, digits=1, known=true)=> known ? safeNum(v,0).toLocaleString('tr-TR', { maximumFractionDigits: digits }) : '<span class="muted">Veri yok</span>';
    const breakdownHtml = lead ? `<div class="business-breakdown"><strong>${escapeHtml(lead.crop)} iÃ§in ${lead.hasMarketBasis ? 'gider daÄŸÄ±lÄ±mÄ±' : 'ekonomik kaynak notu'}</strong><table class="data-table business-table compact" style="margin-top:6px;"><thead><tr><th>Kalem</th><th>Tutar (TL)</th></tr></thead><tbody>${lead.breakdown.map(b=>`<tr><td>${escapeHtml(b.label)}</td><td>${Math.round(safeNum(b.amount,0)).toLocaleString('tr-TR')}</td></tr>`).join('')}</tbody></table><div class="muted" style="margin-top:6px;">${escapeHtml(lead.hasMarketBasis ? (lead.operationsNote || 'Toprak iÅŸleme, ekim/dikim, gÃ¼breleme, ilaÃ§lama, sulama, bakÄ±m ve hasat iÅŸlemleri 2024 gider toplamÄ± Ã¼zerinden oranlanmÄ±ÅŸtÄ±r.') : lead.economicsNote)}</div></div>` : '';
    return `<div class="mini-block business-metrics-card"><h4 style="margin:0 0 8px 0">${escapeHtml(title)}</h4><div class="business-table-wrap"><table class="data-table business-table"><thead><tr><th>ÃœrÃ¼n</th><th>Alan (da)</th><th>Verim (kg/da)</th><th>2024 fiyat (TL/kg)</th><th>Toplam Ã¼retim (kg)</th><th>BrÃ¼t hasÄ±lat</th><th>Toplam gider</th><th>Net kÃ¢r</th><th>Su (mÂ³)</th><th>TL/mÂ³</th><th>Sulama</th></tr></thead><tbody>${econRows.map(r=>`<tr><td><strong>${escapeHtml(r.crop)}</strong><div class="small muted">${escapeHtml(r.season || 'â€”')}</div>${!r.hasMarketBasis ? `<div class="small muted">Ekonomik dayanak: proxy net kÃ¢r</div>` : ''}</td><td>${r.areaDa.toFixed(1)}</td><td>${num(r.yieldKgDa,1,r.hasMarketBasis)}</td><td>${num(r.priceTlKg,2,r.hasMarketBasis)}</td><td>${money(r.totalProductionKg,r.hasMarketBasis)}</td><td>${money(r.grossRevenueTl,r.hasMarketBasis)}</td><td>${money(r.totalCostTl,r.hasMarketBasis)}</td><td>${Math.round(safeNum(r.totalNetProfitTl,0)).toLocaleString('tr-TR')}</td><td>${Math.round(safeNum(r.totalWaterM3,0)).toLocaleString('tr-TR')}</td><td>${r.tlPerM3.toFixed(2)}</td><td>${escapeHtml(r.methodLabel)}<div class="small muted">Ä°ÅŸletme: ${r.opexTlPerDa.toFixed(0)} TL/da â€¢ ${r.waterCostTlPerM3.toFixed(2)} TL/mÂ³</div></td></tr>`).join('')}</tbody><tfoot><tr><th>Toplam</th><th>${totals.area.toFixed(1)}</th><th>â€”</th><th>â€”</th><th>${totals.known ? Math.round(totals.prod).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${totals.known ? Math.round(totals.gross).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${totals.known ? Math.round(totals.cost).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${Math.round(totals.net).toLocaleString('tr-TR')}</th><th>${Math.round(totals.water).toLocaleString('tr-TR')}</th><th>${(totals.net/Math.max(1,totals.water)).toFixed(2)}</th><th>â€”</th></tr></tfoot></table></div>${breakdownHtml}</div>`;
  };

  const note = `<div class="small muted" style="margin-bottom:10px;">Bu ekonomik Ã¶zet 2024 Ã¼rÃ¼n fiyatÄ±, verim, parsel alanÄ±, toplam su ve gider kalemlerini aynÄ± yerde gÃ¶sterir. Tablo kÃ¼Ã§Ã¼k ekranda daralmaz; yatay kaydÄ±rma ile okunur. DetaylÄ± hastalÄ±k/mineral laboratuvar verisi projede olmadÄ±ÄŸÄ± iÃ§in karar mantÄ±ÄŸÄ± ÅŸu anda su kotasÄ±, mevsim, familya/rotasyon, parsel tipi, toprak sÄ±nÄ±fÄ± ve sulama yÃ¶ntemi Ã¼zerinden aÃ§Ä±klanÄ±r.</div>`;
  box.innerHTML = `${note}<div class="official-grid business-grid">${buildTable(current, 'Mevcut desen â€“ ekonomik dayanak', 'current')}${rec.length ? buildTable(rec, `Ã–nerilen desen â€“ ekonomik dayanak (${getScenarioDisplayMeta(objectiveKey).label})`, 'recommended') : '<div class="mini-block"><div class="small muted">Ã–neri oluÅŸtuÄŸunda ekonomik dayanak burada gÃ¶sterilir.</div></div>'}</div>`;
}

function inferSeasonLabelFromCrop(cropName, parcelType=''){
  const nm = normCropName(cropName||'');
  const pt = String(parcelType||'').toLowerCase();
  if(pt === 'orchard' || isPerennialCropName(cropName||'')) return 'Ã‡ok yÄ±llÄ±k / bahÃ§e';
  if(/DOMATES|BIBER|KABAK|PATLICAN|HIYAR|KARPUZ|KAVUN|MISIR|PANCAR|PATATES|AYCICEGI|SOGAN|SARIMSAK|LAHANA|FASULYE|CILEK/.test(nm)) return 'YazlÄ±k';
  if(/BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|FIÄ|YEM_BEZELYESI/.test(nm)) return 'KÄ±ÅŸlÄ±k / serin dÃ¶nem';
  return 'Ana Ã¼rÃ¼n';
}

function isMeaningfulCropRow(r){
  if(!r) return false;
  const name = String(r.name || '').trim();
  if(!name || name === 'â€”' || name === '-' || name.toLowerCase() === 'nan' || name.toLowerCase() === 'undefined' || name.toLowerCase() === 'null') return false;
  const area = safeNum(r.area, 0);
  const water = safeNum(r.waterPerDa, 0);
  const profit = safeNum(r.profitPerDa, 0);
  return area > 0 || water > 0 || profit !== 0;
}

function sanitizePlanRows(rows, parcel){
  const seen = new Set();
  return (Array.isArray(rows) ? rows : []).filter(isMeaningfulCropRow).map(r=>{
    const key = `${normCropName(r.name||'')}|${String(r.season||'').trim()}|${safeNum(r.area,0).toFixed(2)}`;
    if(seen.has(key)) return null;
    seen.add(key);
    const season = String(r.season||'').trim() || inferSeasonLabelFromCrop(r.name, parcel?.parcel_type || '');
    const area = safeNum(r.area, safeNum(parcel?.area_da, 0));
    const waterPerDa = safeNum(r.waterPerDa, 0);
    const profitPerDa = safeNum(r.profitPerDa, 0);
    return {
      ...r,
      season,
      area,
      waterPerDa,
      profitPerDa,
      totalWater: safeNum(r.totalWater, area * waterPerDa),
      totalProfit: safeNum(r.totalProfit, area * profitPerDa),
    };
  }).filter(Boolean);
}

// Crop -> irrigation mapping (from backend meta: data/crop_irrigation_map.json)
// In the "Ã–nerilen ÃœrÃ¼n Deseni" table we show only the best (improved) irrigation suggestion
// compared to the current/default method. We intentionally do not expose all irrigation
// methods as a dropdown.

function _normIrrLookupKeys(cropName){
  const raw = String(cropName||'');
  const k1 = raw;
  const k2 = normCropName(raw);
  const k3 = normCropKey(raw);
  const k4 = normCropKey(raw).replace(/[()]/g,' ').replace(/\s+/g,' ').trim();
  const k5 = normCropKey(raw).replace(/[()]/g,' ').replace(/\s+/g,'_').trim();
  const k6 = normCropKey(raw).replace(/[()]/g,'_').replace(/\s+/g,'_').trim();
  // also try internal style: spaces->underscore
  const k7 = k2.replace(/\s+/g,'_');
  return [k1,k2,k3,k4,k5,k6,k7].filter(Boolean);
}

function irrigationKeysForCrop(cropName){
  const m = STATE.cropIrrigationMap || {};
  let rec = null;
  for(const k of _normIrrLookupKeys(cropName)){
    if(m && m[k]){ rec = m[k]; break; }
  }
  const currentKey = rec?.current || 'sprinkler';
  const suggestedKey = rec?.recommended || recommendedIrrKeyForCrop(cropName, currentKey);
  return { currentKey, suggestedKey };
}

function objectiveFitness(areaDa, crops, x, scenarioKey, currentTotals, parcel){
  // minimize: lower is better
  const xN = normalizeVec(x);

  const water = areaDa * xN.reduce((acc,xi,i)=>acc + xi*crops[i].waterPerDa, 0);

  // temel kÃ¢r
  let profit = areaDa * xN.reduce((acc,xi,i)=>acc + xi*crops[i].profitPerDa, 0);

  // kÃ¶y/ilÃ§e desen uyumu bonusu (TL)
  if(STATE.villagePatterns && STATE.districtPatterns && parcel){
    const bonus = areaDa * xN.reduce((acc,xi,i)=>{
      const cNorm = normCropName(crops[i].name);
      return acc + xi * contextBonusTlPerDa(parcel, cNorm);
    }, 0);
    profit += bonus;
  }

  // toprak/erozyon uygunluÄŸu: bazÄ± Ã¼rÃ¼n tiplerine kÃ¼Ã§Ã¼k ceza/bonus
  if(parcel && parcel.soil){
    const soilAdj = areaDa * xN.reduce((acc,xi,i)=>{
      const t = crops[i].type || cropTypeFromCategory(crops[i].category);
      return acc + xi * soilSuitabilityTlPerDa(parcel.soil, t);
    },0);
    profit += soilAdj;
  }

  // Constraints (soft penalties)
  let penalty = 0;

  // (A) Mutlak su bÃ¼tÃ§esi kÄ±sÄ±tÄ± (yaklaÅŸÄ±k: alan oranÄ±na gÃ¶re parsel bÃ¼tÃ§esi)
  const wBudget = parcelWaterBudget(areaDa, parcel);
  if(water > wBudget){
    const over = (water - wBudget) / Math.max(1, wBudget);
    penalty += over * 50.0; // gÃ¼Ã§lÃ¼ ceza
  }

  // (A2) KuraklÄ±k riski: su yoÄŸun seÃ§imlere ek ceza
  const r = clamp(STATE.droughtRisk ?? 0, 0, 1);
  penalty += r * (water / Math.max(1, wBudget)) * 2.5;

  // (B) Senaryo kÄ±sÄ±tlarÄ± (mevcut desene gÃ¶re)
  // NOTE: UI/back-end may send scenario keys in different forms.
  // Normalize so optimization behaves consistently.
  const sk = normalizeScenarioKey(scenarioKey);
  const curW = safeNum(currentTotals?.totalWater ?? currentTotals?.water);
  const curP = safeNum(currentTotals?.totalProfit ?? currentTotals?.profit);

  if(sk === "water_saving"){
    // Farmer-first constraint: keep production profitable (allow some drop, but avoid collapse)
    const minProfit = curP * 0.85;
    if(curP > 0 && profit < minProfit) penalty += (minProfit - profit) / Math.max(1, minProfit) * 12.0;
    // Strongly discourage increasing water compared to current (drought reality)
    if(curW > 0 && water > curW) penalty += ((water - curW) / Math.max(1, curW)) * 30.0;
    // objective: reduce water
    return (water / Math.max(1, curW || wBudget)) + penalty;
  }

  if(sk === "max_profit"){
    // Still respect water reality: don't exceed current too much
    const maxWater = curW * 1.10;
    if(curW > 0 && water > maxWater) penalty += (water - maxWater) / Math.max(1, maxWater) * 10.0;
    return (-(profit / Math.max(1, curP || 1))) + penalty;
  }

  if(sk === "balanced"){
    // Balanced: prefer less water while keeping profit reasonable
    const minProfit = curP * 0.75;
    if(curP > 0 && profit < minProfit) penalty += (minProfit - profit) / Math.max(1, minProfit) * 8.0;
    // weighted tradeoff
    return (water / Math.max(1, curW || wBudget)) - 0.25 * (profit / Math.max(1, curP || 1)) + penalty;
  }

  // current: no optimization, just feasibility penalties
  return 0 + penalty;
}

// GA: continuous proportions
function runGA(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const popSize = opts.popSize ?? 40;
  const gens = opts.gens ?? 60;
  const elite = opts.elite ?? 4;
  const mutRate = opts.mutRate ?? 0.18;

  function randVec(){
    const x = Array.from({length:n}, ()=>Math.random());
    return normalizeVec(x);
  }

  function crossover(a,b){
    // blend crossover
    const child = a.map((v,i)=>{
      const t = Math.random();
      return t*v + (1-t)*b[i];
    });
    return normalizeVec(child);
  }

  function mutate(x){
    const y = x.slice();
    for(let i=0;i<n;i++){
      if(Math.random() < mutRate){
        y[i] = clamp(y[i] + (Math.random()-0.5)*0.35, 0, 1);
      }
    }
    return normalizeVec(y);
  }

  let pop = Array.from({length:popSize}, randVec);

  for(let g=0; g<gens; g++){
    const scored = pop.map(x=>({x, f: objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel)}))
                      .sort((a,b)=>a.f-b.f);
    const next = scored.slice(0,elite).map(s=>s.x);
    while(next.length < popSize){
      // tournament selection
      const a = scored[Math.floor(Math.random()*Math.min(popSize,12))].x;
      const b = scored[Math.floor(Math.random()*Math.min(popSize,12))].x;
      let child = crossover(a,b);
      child = mutate(child);
      next.push(child);
    }
    pop = next;
  }

  const best = pop.map(x=>({x, f: objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel)}))
                  .sort((a,b)=>a.f-b.f)[0].x;
  return best;
}

// ABC: Artificial Bee Colony (simplified for proportions)
function runABC(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const foodCount = opts.foodCount ?? 25;
  const iters = opts.iters ?? 80;
  const limit = opts.limit ?? 20;

  function randVec(){ return normalizeVec(Array.from({length:n}, ()=>Math.random())); }

  let foods = Array.from({length:foodCount}, randVec);
  let trials = Array.from({length:foodCount}, ()=>0);

  function neighbor(x){
    const y = x.slice();
    const i = Math.floor(Math.random()*n);
    const k = Math.floor(Math.random()*n);
    const phi = (Math.random()*2 - 1); // [-1,1]
    y[i] = clamp(y[i] + phi*(y[i] - y[k]), 0, 1);
    return normalizeVec(y);
  }

  function fitnessVal(x){ return objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel); }

  for(let t=0; t<iters; t++){
    // employed bees
    for(let j=0;j<foodCount;j++){
      const v = neighbor(foods[j]);
      if(fitnessVal(v) < fitnessVal(foods[j])){
        foods[j] = v; trials[j]=0;
      }else trials[j]++;
    }

    // onlooker selection (roulette on inverse fitness)
    const fits = foods.map(fitnessVal);
    const inv = fits.map(f=> 1/(1e-6 + Math.max(0, f + 1))); // keep positive
    const sumInv = inv.reduce((a,b)=>a+b,0);

    for(let o=0;o<foodCount;o++){
      let r = Math.random()*sumInv, pick=0;
      for(let j=0;j<foodCount;j++){ r -= inv[j]; if(r<=0){ pick=j; break; } }
      const v = neighbor(foods[pick]);
      if(fitnessVal(v) < fits[pick]){
        foods[pick] = v; trials[pick]=0;
      }else trials[pick]++;
    }

    // scout
    for(let j=0;j<foodCount;j++){
      if(trials[j] >= limit){
        foods[j] = randVec();
        trials[j] = 0;
      }
    }
  }

  let best = foods[0], bestF = fitnessVal(best);
  for(const x of foods){
    const f = fitnessVal(x);
    if(f < bestF){ best=x; bestF=f; }
  }
  return best;
}

// ACO: Ant Colony (discrete allocations with 20 units = 5% each)
function runACO(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const ants = opts.ants ?? 30;
  const iters = opts.iters ?? 60;
  const units = opts.units ?? 20; // 5% resolution
  const evap = opts.evap ?? 0.15;

  // pheromone for each crop choice per unit position
  let tau = Array.from({length:units}, ()=>Array.from({length:n}, ()=>1.0));

  function heuristic(i){
    // scenario-dependent desirability
    if(scenarioKey === "su_tasarruf"){
      return 1/(1 + crops[i].waterPerDa); // less water better
    }
    if(scenarioKey === "maks_kar"){
      return 1 + crops[i].profitPerDa/10000; // more profit better
    }
    // balanced (not used here)
    return 1;
  }
  const eta = crops.map((_,i)=>heuristic(i));

  function construct(){
    const counts = Array.from({length:n}, ()=>0);
    for(let u=0;u<units;u++){
      // probability proportional to tau^a * eta^b
      const a=1.0,b=2.0;
      const weights = tau[u].map((t,i)=>Math.pow(t,a)*Math.pow(eta[i],b));
      const sumW = weights.reduce((x,y)=>x+y,0);
      let r = Math.random()*sumW, pick=0;
      for(let i=0;i<n;i++){ r -= weights[i]; if(r<=0){ pick=i; break; } }
      counts[pick] += 1;
    }
    // proportions
    const x = counts.map(c=>c/units);
    return normalizeVec(x);
  }

  function fit(x){ return objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel); }

  let globalBest = null, globalBestF = Infinity;

  for(let it=0; it<iters; it++){
    const solutions = [];
    for(let a=0;a<ants;a++){
      const x = construct();
      const f = fit(x);
      solutions.push({x,f});
      if(f < globalBestF){ globalBestF=f; globalBest=x; }
    }

    // evaporate
    for(let u=0;u<units;u++){
      for(let i=0;i<n;i++){
        tau[u][i] *= (1-evap);
        tau[u][i] = Math.max(0.01, tau[u][i]);
      }
    }

    // reinforce best few
    solutions.sort((a,b)=>a.f-b.f);
    const topK = Math.max(1, Math.floor(ants*0.15));
    for(let k=0;k<topK;k++){
      const x = solutions[k].x;
      const delta = 1/(1e-6 + Math.max(0, solutions[k].f + 1));
      for(let u=0;u<units;u++){
        for(let i=0;i<n;i++){
          tau[u][i] += delta * x[i];
        }
      }
    }
  }

  return globalBest ?? normalizeVec(Array.from({length:n}, ()=>1/n));
}


function getCandidateCropsForParcel(p){
  // Senaryo kaynaÄŸÄ± Ã¶nemlidir: Senaryo-2 seÃ§ildiÄŸinde, sezon dosyalarÄ±nda
  // bazÄ± parsel/yÄ±l kombinasyonlarÄ± eksik olsa bile "anlaÅŸÄ±lan Ã¼rÃ¼n havuzu"
  // mutlaka adaylar iÃ§inde bulunmalÄ±dÄ±r.
  const seasonSource = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';

  // Senaryo-2: aday havuzu sadece mutabÄ±k Ã¼rÃ¼nlerden oluÅŸsun.
  // Sezon dosyasÄ± farklÄ± Ã¼rÃ¼nler iÃ§erebildiÄŸi iÃ§in (domates/biber vs.)
  // bu modda "candidatesByParcel" kullanmÄ±yoruz.
  if(seasonSource === 's2'){
    ensureScenario2Catalog();
    const catalog = STATE.cropCatalog || {};
    return (STATE.S2_PRIMARY_POOL || S2_PRIMARY_POOL || [])
      .filter(Boolean)
      .map(k=>({
        name: k,
        waterPerDa: clamp(safeNum(catalog[k]?.waterPerDa, S2_DEFAULT_PARAMS[k]?.waterPerDa || 0), 0, 3000),
        profitPerDa: clamp(safeNum(catalog[k]?.profitPerDa, S2_DEFAULT_PARAMS[k]?.profitPerDa || 0), -50000, 50000)
      }))
      .filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
  }

  // PRIMARY: use enhanced season candidates for this parcel *and selected year* (real data).
  // This makes parcel switching and year switching actually change recommendations.
  const pid = p?.id;
  const y = +STATE.selectedWaterYear;

  // 1) Year-specific candidates
  let m = null;
  if(STATE.candidatesByParcelYear && isFinite(y) && pid){
    const byParcel = STATE.candidatesByParcelYear.get(y);
    m = byParcel ? byParcel.get(pid) : null;
  }

  // 2) Fallback: all-years candidates
  if((!m || !m.size) && STATE.candidatesByParcel && pid){
    m = STATE.candidatesByParcel.get(pid);
  }
  if(m && m.size){
    const arr = [];
    for(const [ck,a] of m.entries()){
      const area = a.area || 1;
      const waterPerDa = a.water / area;
      const profitPerDa = a.profit / area;
      arr.push({ name: a.name || ck, waterPerDa, profitPerDa, irrigationText: a.irrigationText || '', irrigationKey: a.irrigationKey || '', parcelSpecific: true });
    }
    // Crop catalog parametreleri (Kc, ekonomi vb.)
    if(STATE.cropCatalog){
      for(const c of arr){
        const cat = STATE.cropCatalog[normCropName(c.name)];
        if(!cat) continue;

        // Su/da: eksikse katalogdan doldur
        // Only overwrite missing/invalid values. Do NOT treat 0 as invalid (dryland).
        if((!isFinite(c.waterPerDa) || c.waterPerDa<0) && isFinite(cat.waterPerDa) && cat.waterPerDa>=0){
          c.waterPerDa = cat.waterPerDa;
        }

        // KÃ¢r/da: fiyat/teÅŸvik yÃ¼klenmiÅŸse (override) katalogdaki kÃ¢rÄ± tercih et
        if(STATE.marketOverridesActive && cat._profit_overridden && isFinite(cat.profitPerDa)){
          c.profitPerDa = cat.profitPerDa;
        }else if((!isFinite(c.profitPerDa)) && isFinite(cat.profitPerDa)){
          c.profitPerDa = cat.profitPerDa;
        }

        // Dinamik meteoroloji aktifse: ET0/yaÄŸÄ±ÅŸ + Kc ile sezonluk sulama ihtiyacÄ±nÄ± hesapla
        if(STATE.dynamicIrrigation){
          const irr = computeSeasonIrrigation(p, c.name);
          if(irr && irr.mode !== "none" && isFinite(irr.sumGross) && irr.sumGross>0){
            // sumGross (mm) â‰ˆ m3/da
            const dyn = irr.sumGross;
            // Ã§ok sert sÄ±Ã§ramalarÄ± azaltmak iÃ§in harmanla
            const base = (isFinite(c.waterPerDa) && c.waterPerDa>0) ? c.waterPerDa : dyn;
            c.waterPerDa = 0.4*base + 0.6*dyn;
          }
        }
      }
    }
    // Senaryo-2: Ã¼rÃ¼n havuzunu garanti et (meyve + tarla bitkileri)
    if(seasonSource === 's2'){
      const catalog = STATE.cropCatalog || {};
      const must = (STATE.S2_PRIMARY_POOL || []).filter(Boolean);
      const have = new Set(arr.map(x=>normCropName(x.name)));
      for(const ck of must){
        if(have.has(ck)) continue;
        const cat = catalog[ck];
        if(cat && isFinite(cat.waterPerDa) && isFinite(cat.profitPerDa)){
        arr.push({ name: ck, waterPerDa: cat.waterPerDa, profitPerDa: cat.profitPerDa, parcelSpecific: false });
        }
      }
    }

    // Allow dryland / rainfed candidates (waterPerDa can be 0).
    // Previously we filtered out waterPerDa==0 which removed cereals/legumes that can be grown
    // with minimal irrigation, leading to empty candidate sets and "0" results.
    return arr
      .map(c=>({
        ...c,
        // AÅŸÄ±rÄ± uÃ§ deÄŸerleri (Ã¶lÃ§ek hatalarÄ±) UI'da patlatmasÄ±n diye yumuÅŸak tavan
        waterPerDa: clamp(safeNum(c.waterPerDa,0), 0, 3000),
        profitPerDa: clamp(safeNum(c.profitPerDa,0), -50000, 50000)
      }))
      .filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
  }

  // FALLBACK (should rarely happen): use global catalog
  let candidates = cropCatalog.slice();
  if(STATE.cropCatalog){
    candidates = candidates.map(c=>{
      const cat = STATE.cropCatalog[normCropName(c.name)];
      return cat ? { ...c, waterPerDa: cat.waterPerDa, profitPerDa: cat.profitPerDa } : c;
    });
  }
  return candidates.map(c=>({ ...c, parcelSpecific: false })).filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
}

// Senaryo-2 bahce/perennial kÄ±sÄ±tÄ±: meyve bahcesi olan parselde Ã¼rÃ¼n deÄŸiÅŸmez;
// bunun yerine su tasarrufu senaryolarÄ±nda sulama planÄ± (kÄ±sÄ±ntÄ±lÄ± damla) Ã¶nerilir.
const PERENNIAL_SET = new Set([
  // Senaryo-2: Ã§ok yÄ±llÄ±k Ã¼rÃ¼nler (bahce + baÄŸ + yonca)
  // Not: burada anahtarlar normCropName() Ã§Ä±ktÄ±sÄ± ile aynÄ± olmalÄ±.
  normCropName('ELMA'),
  normCropName('KÄ°RAZ'),
  normCropName('BAÄ (ÃœZÃœM)'),
  normCropName('CEVÄ°Z'),
  normCropName('ARMUT'),
  normCropName('ÅEFTALÄ°'),
  normCropName('NEKTARÄ°N'),
  normCropName('KAYISI'),
  normCropName('VÄ°ÅNE'),
  normCropName('ERÄ°K'),
  normCropName('YONCA (YEÅÄ°LOT)')
]);

function isPerennialCropName(name){
  const k = normCropName(name);
  return PERENNIAL_SET.has(k) || /BADEM|NEKTAR|KAYSI|KAYISI|AYVA|DUT|CILEK|CILEK|IGDE|ZERDALI|KIRAZ|ELMA|ARMUT|VISNE|ERIK|BAG|UZUM|CEVIZ|SEFTALI/.test(k);
}

function isAnnualFieldCandidateName(name){
  const k = normCropName(name);
  if(!k || isPerennialCropName(name)) return false;
  if(/DOMATES|BIBER|KABAK|PATLICAN|HIYAR|KARPUZ|KAVUN|SOGAN|SARIMSAK|LAHANA|MARUL|ISPANAK|HAVUC|TURP|BAMYA|FASULYE/.test(k)) return true;
  if(/BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|YEM|BEZELYE|AYCICEGI|MISIR|PANCAR|PATATES|KIMYON|NADAS/.test(k)) return true;
  return false;
}

function dominantCropNameForParcel(p){
  // currentRows Ã¼zerinden en bÃ¼yÃ¼k alanlÄ± Ã¼rÃ¼nÃ¼ al
  let best = null;
  for(const c of (p.cropCurrent||[])){
    if(!best || (c.area||0) > (best.area||0)) best = c;
  }
  return best ? best.name : null;
}

function s2IrrigationAdjust(scenarioKey){
  if(scenarioKey === 'su_tasarruf') return {
    wmul:0.82,
    pmul:0.95,
    label:'Damla sulama + kontrollÃ¼ kÄ±sÄ±ntÄ± (%18). AmaÃ§: ana Ã¼rÃ¼nÃ¼ korurken suyu azaltmak ve TL/mÂ³ verimini yÃ¼kseltmek.'
  };
  if(scenarioKey === 'maks_kar') return {
    wmul:0.96,
    pmul:1.06,
    label:'Tam zamanlÄ± damla sulama + verim odaklÄ± yÃ¶netim. AmaÃ§: ana Ã¼rÃ¼nÃ¼ korurken ticari getiriyi artÄ±rmak.'
  };
  return {
    wmul:0.90,
    pmul:1.00,
    label:'Damla sulama + hafif kÄ±sÄ±ntÄ± (%10). AmaÃ§: su ve kÃ¢r dengesini birlikte korumak.'
  };
}

function orchardCropMetaForUi(name){
  const cat = STATE.cropCatalog || {};
  const raw = String(name||'').trim();
  const variants = [];
  if(raw) variants.push(raw);
  if(raw && raw.includes('_')) variants.push(raw.replace(/_/g,' '));
  const pretty = prettyCropName(raw);
  if(pretty && pretty !== raw) variants.push(pretty);
  if(pretty && pretty.includes('_')) variants.push(pretty.replace(/_/g,' '));
  for(const v of variants){
    const k = normCropName(v);
    if(cat[k]){
      let wNet = safeNum(cat[k].waterPerDa);
      let pr = safeNum(cat[k].profitPerDa);
      if(!(isFinite(wNet) && wNet>0)){
        const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, k);
        if(isFinite(ws) && ws>0) wNet = ws;
      }
      return { waterNet: wNet, profit: pr };
    }
  }
  const fallback = {
    'MERCIMEK': { waterNet: 210, profit: 3600 },
    'NOHUT': { waterNet: 312.36, profit: 3200 },
    'FIÄ (YEÅILOT)': { waterNet: 155.83, profit: 4500 },
    'ARPA (YEÅILOT)': { waterNet: 288.12, profit: 4200 },
  };
  return fallback[normCropName(raw)] || { waterNet: 0, profit: 0 };
}

function orchardAlternativeScenarioMetrics(mainCrop, parcelAreaDa, objectiveKey, currentMainRow, list){
  const rows = Array.isArray(list) && list.length ? list : orchardInterrowAlternativesForMain(mainCrop);
  const currentKey = currentMainRow?.irrigationCurrentKey || irrKeyFromText(currentMainRow?.irrigationCurrentText || '') || 'drip';
  const out = rows.map((alt, idx)=>{
    const meta = orchardCropMetaForUi(alt.name);
    const isProfit = objectiveKey === 'maks_kar';
    const share = safeNum(isProfit ? (alt.shareProfit || alt.share_profit) : (alt.shareWater || alt.share_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.32 : 0.27) : (isProfit ? 0.18 : 0.30));
    const waterMult = safeNum(isProfit ? (alt.waterMultProfit || alt.water_mult_profit) : (alt.waterMultWater || alt.water_mult_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.84 : 0.74) : (isProfit ? 0.68 : 0.58));
    const profitMult = safeNum(isProfit ? (alt.profitMultProfit || alt.profit_mult_profit) : (alt.profitMultWater || alt.profit_mult_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.95 : 0.88) : (isProfit ? 0.28 : 0.40));
    const area = +(safeNum(parcelAreaDa, 0) * share).toFixed(1);
    const suggestedKey = recommendedIrrKeyForCrop(alt.name, currentKey) || currentKey;
    const waterGross = deliveredWaterPerDa(meta.waterNet * waterMult, suggestedKey);
    const profitPerDa = +(meta.profit * profitMult).toFixed(2);
    const totalWater = +(area * waterGross).toFixed(2);
    const totalProfit = +(area * profitPerDa).toFixed(2);
    const tlPerM3 = totalWater > 0 ? (totalProfit / totalWater) : 0;
    const score = isProfit ? (totalProfit + tlPerM3 * 250) : (tlPerM3 * 1100 - totalWater * 0.10 + totalProfit * 0.10);
    return {
      ...alt,
      area,
      irrigationKey: suggestedKey,
      irrigationText: irrigationLabel(suggestedKey),
      waterPerDa: +waterGross.toFixed(3),
      profitPerDa,
      totalWater,
      totalProfit,
      tlPerM3: +tlPerM3.toFixed(2),
      score: +score.toFixed(2),
      rank: idx + 1,
      objectiveLabel: isProfit ? 'KÃ¢r odaklÄ± sÄ±ra arasÄ± senaryo' : 'Su verimliliÄŸi odaklÄ± sÄ±ra arasÄ± senaryo'
    };
  }).filter(x=>x.area > 0 && x.waterPerDa >= 0);
  out.sort((a,b)=>safeNum(b.score)-safeNum(a.score));
  out.forEach((x,i)=>x.rank=i+1);
  return out;
}


function _seasonModeKey(){
  const raw = (document.getElementById('seasonSourceSel')?.value || STATE.seasonSource || 's1');
  return String(raw || 's1').toLowerCase() === 's2' ? 's2' : 's1';
}

function _objectiveScorePattern(totalWater, totalProfit, scenarioKey){
  const obj = normalizeScenarioKey(scenarioKey);
  const eff = totalWater > 0 ? (totalProfit / totalWater) : 0;
  if(obj === 'water_saving' || obj === 'water_efficiency' || obj === 'su_tasarruf'){
    return eff * 1000 - totalWater * 0.08 + totalProfit * 0.04;
  }
  if(obj === 'max_profit' || obj === 'maks_kar'){
    return totalProfit + eff * 250;
  }
  return totalProfit * 0.5 + eff * 500 - totalWater * 0.03;
}

function _patternPeakMonthLabel(pattern){
  const txt = String(pattern?.seasonLabel || pattern?.season || '').toLowerCase();
  if(txt.includes('Ã§ok yÄ±llÄ±k') || txt.includes('bahÃ§e')) return 'Haz-Tem';
  if(txt.includes('yaz')) return 'Tem-AÄŸu';
  if(txt.includes('kÄ±ÅŸ')) return 'Nis-May';
  if(txt.includes('rotasyon') || txt.includes('+')) return 'Haz-Tem';
  return 'Temmuz';
}

function cropSuitabilityForParcel(parcel, cropName){
  const lccRaw = String(parcel?.land_capability_class || parcel?.soil?.class || '').trim();
  const lcc = lccRaw && !/veri\s*yok/i.test(lccRaw) ? lccRaw.toUpperCase().replace(/\.?\s*s[Ä±i]n[Ä±i]f/i,'').trim() : '';
  const key = lcc ? `${lcc}|${normCropName(cropName)}` : '';
  const rec = key && STATE.cropSuitabilityByKey instanceof Map ? STATE.cropSuitabilityByKey.get(key) : null;
  if(rec){
    const score = clamp(safeNum(rec.score, 0.85), 0, 1);
    return {
      score,
      label: score >= 0.85 ? 'YÃ¼ksek' : (score >= 0.70 ? 'Orta' : (score >= 0.60 ? 'SÄ±nÄ±rda' : 'Uygun deÄŸil')),
      basis: rec.basis || rec.status || 'LCC x Ã¼rÃ¼n uygunluk tablosu'
    };
  }
  const isPerennial = isPerennialCropName(cropName);
  const parcelType = inferParcelTypeKey(parcel);
  const score = (parcelType === 'orchard' && !isPerennial) ? 0.68 : (parcelType !== 'orchard' && isPerennial ? 0.62 : 0.78);
  return {
    score,
    label: 'Proxy',
    basis: 'Parsel toprak sÄ±nÄ±fÄ± eksik; parsel tipi + Ã¼rÃ¼n grubu proxy kullanÄ±ldÄ±.'
  };
}

function patternSuitabilitySummary(parcel, rows){
  const list = (rows || []).filter(Boolean).map(r=>cropSuitabilityForParcel(parcel, r.name || r.mainCrop || r.crop));
  if(!list.length) return { score:0, label:'-', basis:'ÃœrÃ¼n satÄ±rÄ± yok' };
  const minScore = Math.min(...list.map(x=>safeNum(x.score,0)));
  const weakest = list.sort((a,b)=>safeNum(a.score)-safeNum(b.score))[0];
  return { score:minScore, label:weakest?.label || '-', basis:weakest?.basis || '' };
}

function _fieldCandidatePool(parcel, currentRows){
  const cat = STATE.cropCatalog || {};
  const parcelType = inferParcelTypeKey(parcel);
  const out = [];
  const localCandidates = (typeof getCandidateCropsForParcel === 'function')
    ? getCandidateCropsForParcel(parcel).filter(c=>c && c.parcelSpecific)
    : [];
  const seasonMode = _seasonModeKey();
  if(localCandidates.length){
    for(const c of localCandidates){
      const name = c.name || c.crop || '';
      const waterPerDa = safeNum(c.waterPerDa, 0);
      const profitPerDa = safeNum(c.profitPerDa, 0);
      if(waterPerDa < 0 || !(profitPerDa > 0)) continue;
      if(parcelType === 'orchard' && !isPerennialCropName(name)) continue;
      if(parcelType !== 'orchard' && isPerennialCropName(name)) continue;
      if(parcelType !== 'orchard' && !isAnnualFieldCandidateName(name)) continue;
      const keys = irrigationKeysForCrop(name);
      const suit = cropSuitabilityForParcel(parcel, name);
      if(safeNum(suit.score, 0) < 0.60) continue;
      out.push({
        name,
        waterPerDa,
        profitPerDa,
        tlPerM3: waterPerDa > 0 ? (profitPerDa / waterPerDa) : 0,
        irrigationKey: keys.suggestedKey || keys.currentKey || 'sprinkler',
        family: (typeof familyOf === 'function') ? familyOf(name) : '',
        suitability: suit,
      });
    }
    // Senaryo-1'de yerel/parsel adaylarÄ± yeterlidir. Senaryo-2'de ise yazlÄ±k+kÄ±ÅŸlÄ±k
    // desen kurabilmek iÃ§in katalogdaki gÃ¼venli yÄ±llÄ±k adaylarÄ± da eklemeye devam ederiz.
    if(seasonMode !== 's2'){
      const seenLocal = new Set();
      return out.filter(x=>{
        const k = normCropName(x.name);
        if(seenLocal.has(k)) return false;
        seenLocal.add(k);
        return true;
      });
    }
  }
  for(const k in cat){
    const c = cat[k] || {};
    const name = c.displayName || c.name || prettyCropName(k);
    const waterPerDa = safeNum(c.waterPerDa, 0);
    const profitPerDa = safeNum(c.profitPerDa, 0);
    if(!(waterPerDa > 0) || !(profitPerDa > 0)) continue;
    if(parcelType === 'orchard' && !isPerennialCropName(name)) continue;
    if(parcelType !== 'orchard' && isPerennialCropName(name)) continue;
    if(parcelType !== 'orchard' && !isAnnualFieldCandidateName(name)) continue;
    const suit = cropSuitabilityForParcel(parcel, name);
    if(safeNum(suit.score, 0) < 0.60) continue;
    out.push({
      name,
      waterPerDa,
      profitPerDa,
      tlPerM3: waterPerDa > 0 ? (profitPerDa / waterPerDa) : 0,
      irrigationKey: irrigationKeysForCrop(name).suggestedKey || irrigationKeysForCrop(name).currentKey || 'sprinkler',
      family: (typeof familyOf === 'function') ? familyOf(name) : '',
      suitability: suit,
    });
  }
  const seen = new Set();
  return out.filter(x=>{
    const k = normCropName(x.name);
    if(seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

function buildUiAlternativePatterns(parcel, currentRows, recRows, recMeta, scenarioKey){
  const scenarioType = _seasonModeKey();
  const areaDa = safeNum(parcel?.area_da, 0);
  const currentMain = Array.isArray(currentRows) && currentRows.length ? [...currentRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  const recMain = Array.isArray(recRows) && recRows.length ? recRows[0] : currentMain;
  const isOrchard = !!(parcel?.parcel_type === 'orchard' || parcel?.is_orchard || (currentMain && isPerennialCropName(currentMain.name)) || recMeta?.orchardKeepMainCrop);
  const patterns = [];
  const selectedRecommendationPattern = (() => {
    const recList = Array.isArray(recRows) ? recRows.filter(Boolean) : [];
    if(!recList.length || !areaDa) return null;
    const totalWater = recList.reduce((a,r)=>a+safeNum(r.totalWater, safeNum(r.area,0)*safeNum(r.waterPerDa,0)),0);
    const totalProfit = recList.reduce((a,r)=>a+safeNum(r.totalProfit, safeNum(r.area,0)*safeNum(r.profitPerDa,0)),0);
    const mainRow = recList[0];
    const secondRow = recList.find((r,idx)=>idx>0 && normCropName(r.name)!==normCropName(mainRow?.name));
    const suit = patternSuitabilitySummary(parcel, recList);
    const secondName = secondRow ? prettyCropName(secondRow.name) : 'â€”';
    return {
      selectedRecommendation: true,
      patternName: secondRow ? `${prettyCropName(mainRow.name)} + ${secondName}` : `${prettyCropName(mainRow.name)} Ã¶nerilen desen`,
      mainCrop: prettyCropName(mainRow.name),
      secondaryCrop: secondName,
      areaSplit: secondRow ? 'SeÃ§ili algoritma deseni; Ã¼rÃ¼nler kendi dÃ¶neminde deÄŸerlendirilir' : 'Ana Ã¼rÃ¼n %100',
      irrigation: recList.map(r=>r.irrigationSuggested || irrigationLabel(r.irrigationSuggestedKey || r.irrigationCurrentKey)).filter(Boolean).join(' / '),
      totalWater,
      totalProfit,
      tlPerM3: totalWater > 0 ? totalProfit / totalWater : 0,
      peakMonth: recList.map(r=>cropPeakMonthLabel(r.name)).filter(Boolean).join(' / '),
      seasonLabel: secondRow ? 'SeÃ§ili yÄ±llÄ±k desen' : (inferSeasonFromCropName(mainRow.name) || 'Tek sezon'),
      note: 'SeÃ§ili senaryo + algoritma Ã¶nerisi',
      suitability: `${suit.label || 'Proxy'} (${Math.round(safeNum(suit.score,0)*100)}%)`,
      suitabilityBasis: suit.basis || '',
      growthDays: recList.map(r=>stageTotalDays(stageParamsForCrop(r.name))).join('+'),
      productionWindow: recList.map(r=>cropProductionWindowLabel(r.name)).join(' / '),
      score: Number.POSITIVE_INFINITY
    };
  })();
  if(isOrchard && currentMain){
    const main = prettyCropName(currentMain.name);
    const baseRow = recMain || currentMain;
    const baseWater = safeNum(baseRow.totalWater, safeNum(currentMain.totalWater,0));
    const baseProfit = safeNum(baseRow.totalProfit, safeNum(currentMain.totalProfit,0));
    patterns.push({
      rank: 1,
      patternName: `${main} + temel bahÃ§e yÃ¶netimi`,
      mainCrop: main,
      secondaryCrop: 'â€”',
      areaSplit: 'Ana Ã¼rÃ¼n %100',
      irrigation: baseRow.irrigationSuggestedText || baseRow.irrigationSuggested || baseRow.irrigationCurrentText || 'Damla',
      totalWater: baseWater,
      totalProfit: baseProfit,
      tlPerM3: baseWater > 0 ? (baseProfit/baseWater) : 0,
      peakMonth: _patternPeakMonthLabel({season:'BahÃ§e (Ã§ok yÄ±llÄ±k)'}),
      seasonLabel: 'BahÃ§e (Ã§ok yÄ±llÄ±k)',
      note: 'Ana Ã¼rÃ¼n korunur; Ã¶neri sulama yÃ¶ntemi ve yÃ¶netim desenine dayanÄ±r.',
      score: _objectiveScorePattern(baseWater, baseProfit, scenarioKey)
    });
    const altMetrics = (Array.isArray(recMeta?.orchardAlternativeMetrics) && recMeta.orchardAlternativeMetrics.length)
      ? recMeta.orchardAlternativeMetrics
      : orchardAlternativeScenarioMetrics(main, areaDa, scenarioKey, baseRow, orchardAlternativeListFallback(currentRows, recRows, recMeta));
    altMetrics.forEach((a)=>{
      const totalWater = baseWater + safeNum(a.totalWater,0);
      const totalProfit = baseProfit + safeNum(a.totalProfit,0);
      patterns.push({
        patternName: `${main} + ${prettyCropName(a.name)}`,
        mainCrop: main,
        secondaryCrop: prettyCropName(a.name),
        areaSplit: `Ana Ã¼rÃ¼n %100 + sÄ±ra arasÄ± ~%${Math.round((safeNum(a.area,0)/Math.max(1,areaDa))*100)}`,
        irrigation: `${baseRow.irrigationSuggestedText || baseRow.irrigationSuggested || baseRow.irrigationCurrentText || 'Damla'} / ${a.irrigationText || 'Damla'}`,
        totalWater,
        totalProfit,
        tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
        peakMonth: 'Haz-Tem',
        seasonLabel: 'BahÃ§e + sÄ±ra arasÄ±',
        note: a.note || 'SÄ±ra arasÄ± / Ã¶rtÃ¼ bitkisi yÃ¶netim alternatifi',
        score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) + safeNum(a.score,0)*0.01
      });
    });
  } else {
    const pool = _fieldCandidatePool(parcel, currentRows);
    const obj = normalizeScenarioKey(scenarioKey);
    pool.sort((a,b)=>{
      const sa = clamp(safeNum(a?.suitability?.score, 0.78), 0, 1);
      const sb = clamp(safeNum(b?.suitability?.score, 0.78), 0, 1);
      if(obj === 'max_profit' || obj === 'maks_kar') return (safeNum(b.profitPerDa)*sb)-(safeNum(a.profitPerDa)*sa);
      return (safeNum(b.tlPerM3)*sb)-(safeNum(a.tlPerM3)*sa) || safeNum(a.waterPerDa)-safeNum(b.waterPerDa);
    });
    const top = pool.slice(0, Math.max(10, pool.length ? 10 : 0));
    if(scenarioType === 's1'){
      top.forEach((c)=>{
        const totalWater = areaDa * safeNum(c.waterPerDa,0);
        const totalProfit = areaDa * safeNum(c.profitPerDa,0);
        const st = stageParamsForCrop(c.name);
        const days = stageTotalDays(st);
        patterns.push({
          patternName: `${prettyCropName(c.name)} tek Ã¼rÃ¼n`,
          mainCrop: prettyCropName(c.name),
          secondaryCrop: 'â€”',
          areaSplit: 'Ana Ã¼rÃ¼n %100',
          irrigation: irrigationLabel(c.irrigationKey),
          totalWater,
          totalProfit,
          tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
          peakMonth: cropPeakMonthLabel(c.name),
          seasonLabel: inferSeasonFromCropName(c.name) || 'Tek sezon',
          note: 'Tek Ã¼rÃ¼nlÃ¼ parsel senaryosu',
          suitability: `${c.suitability?.label || 'Proxy'} (${Math.round(safeNum(c.suitability?.score,0)*100)}%)`,
          suitabilityBasis: c.suitability?.basis || '',
          growthDays: days,
          productionWindow: cropProductionWindowLabel(c.name),
          score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) * Math.max(0.6, safeNum(c.suitability?.score,0.78))
        });
      });
    } else {
      const winterNames = /BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|YEM|BEZELYE|SOGAN|SARIMSAK|LAHANA|MARUL|ISPANAK|TURP/;
      const summerNames = /AYCICEGI|MISIR|PANCAR|PATATES|KIMYON|DOMATES|BIBER|KABAK|HAVUC|FASULYE/;
      const first = top.filter(c=>isAnnualFieldCandidateName(c.name)).slice(0,8);
      const seconds = pool
        .filter(x=>isAnnualFieldCandidateName(x.name))
        .filter(x=>safeNum(x.suitability?.score,0.78) >= 0.65)
        .slice(0,30);
      first.forEach((c1, idx)=>{
        const c1Key = normCropName(c1.name);
        const c1SeasonGuess = inferSeasonFromCropName(c1.name);
        const c1Winter = c1SeasonGuess === 'KÄ±ÅŸlÄ±k' || winterNames.test(c1Key);
        const c1Summer = c1SeasonGuess === 'YazlÄ±k' || summerNames.test(c1Key);
        const c2 = seconds.find(x=>{
          const xk = normCropName(x.name);
          if(x.family && c1.family && x.family === c1.family) return false;
          const xSeasonGuess = inferSeasonFromCropName(x.name);
          const xWinter = xSeasonGuess === 'KÄ±ÅŸlÄ±k' || winterNames.test(xk);
          const xSummer = xSeasonGuess === 'YazlÄ±k' || summerNames.test(xk);
          return c1Winter ? xSummer : (c1Summer ? xWinter : xWinter);
        }) || null;
        const s1Alt = inferSeasonFromCropName(c1.name);
        const s2Alt = c2 ? inferSeasonFromCropName(c2.name) : '';
        const isSequential = !!(c2 && s1Alt && s2Alt && s1Alt !== s2Alt);
        const a1 = areaDa;
        const a2 = c2 && isSequential ? areaDa : 0;
        const totalWater = a1*safeNum(c1.waterPerDa,0) + (c2 ? a2*safeNum(c2.waterPerDa,0) : 0);
        const totalProfit = a1*safeNum(c1.profitPerDa,0) + (c2 ? a2*safeNum(c2.profitPerDa,0) : 0);
        const st1 = stageParamsForCrop(c1.name);
        const st2 = c2 ? stageParamsForCrop(c2.name) : null;
        const days1 = stageTotalDays(st1);
        const days2 = st2 ? stageTotalDays(st2) : 0;
        const suitScore = Math.min(safeNum(c1.suitability?.score,0.78), c2 ? safeNum(c2.suitability?.score,0.78) : 1);
        patterns.push({
          patternName: c2 ? `${prettyCropName(c1.name)} + ${prettyCropName(c2.name)}` : `${prettyCropName(c1.name)} tek Ã¼rÃ¼n`,
          mainCrop: prettyCropName(c1.name),
          secondaryCrop: c2 ? prettyCropName(c2.name) : 'â€”',
          areaSplit: c2 ? 'AynÄ± parselde ardÄ±ÅŸÄ±k sezon; her Ã¼rÃ¼n kendi dÃ¶neminde %100 alan' : 'Ana Ã¼rÃ¼n %100',
          irrigation: c2 ? `${irrigationLabel(c1.irrigationKey)} / ${irrigationLabel(c2.irrigationKey)}` : irrigationLabel(c1.irrigationKey),
          totalWater,
          totalProfit,
          tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
          peakMonth: c2 ? `${cropPeakMonthLabel(c1.name)} / ${cropPeakMonthLabel(c2.name)}` : cropPeakMonthLabel(c1.name),
          seasonLabel: c2 ? 'Ã‡ift Ã¼rÃ¼n / desen' : (inferSeasonFromCropName(c1.name) || 'Tek sezon'),
          note: c2 ? 'YÄ±llÄ±k desen olarak birlikte test edilir; 2. Ã¼rÃ¼n baÄŸÄ±msÄ±z Ã¶neri deÄŸildir.' : 'Tek Ã¼rÃ¼nlÃ¼ fallback',
          suitability: `${c1.suitability?.label || 'Proxy'} / ${c2 ? (c2.suitability?.label || 'Proxy') : '-'}`,
          suitabilityBasis: [c1.suitability?.basis, c2?.suitability?.basis].filter(Boolean).join(' | '),
          growthDays: c2 ? `${days1}+${days2}` : days1,
          productionWindow: c2 ? `${cropProductionWindowLabel(c1.name)} / ${cropProductionWindowLabel(c2.name)}` : cropProductionWindowLabel(c1.name),
          score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) * Math.max(0.6, suitScore)
        });
      });
    }
  }
  let displayPatterns = patterns.sort((a,b)=>safeNum(b.score)-safeNum(a.score));
  if(selectedRecommendationPattern){
    const selA = normCropName(selectedRecommendationPattern.mainCrop);
    const selB = normCropName(selectedRecommendationPattern.secondaryCrop);
    displayPatterns = [
      selectedRecommendationPattern,
      ...displayPatterns.filter(p=>{
        const a = normCropName(p.mainCrop);
        const b = normCropName(p.secondaryCrop);
        if(scenarioType === 's2' && selB && selB !== normCropName('â€”')){
          return [a,b].sort().join('|') !== [selA,selB].sort().join('|');
        }
        return !(a === selA && b === selB);
      })
    ];
  }
  const seen = new Set();
  return displayPatterns.filter(p=>{
    const a = normCropName(p.mainCrop);
    const b = normCropName(p.secondaryCrop);
    const k = (scenarioType === 's2' && b && b !== normCropName('â€”')) ? [a,b].sort().join('|') : `${a}|${b}`;
    if(seen.has(k)) return false;
    seen.add(k);
    return true;
  }).slice(0,8).map((p,idx)=>({ ...p, rank: idx+1 }));
}



function pairingForCrop(name){
  const raw = String(name||'').trim();
  const candidates = [];
  if(raw) candidates.push(raw);
  if(raw && raw.includes('_')) candidates.push(raw.replace(/_/g,' '));
  if(raw) candidates.push(prettyCropName(raw));
  if(raw && raw.includes('_')) candidates.push(prettyCropName(raw).replace(/_/g,' '));
  // direct match
  for(const c of candidates){
    if(S1_PAIRING[c]) return S1_PAIRING[c];
  }
  // case-insensitive match (space/underscore normalized)
  const target = raw.replace(/_/g,' ').toUpperCase();
  for(const k in S1_PAIRING){
    if(String(k).replace(/_/g,' ').toUpperCase()===target) return S1_PAIRING[k];
  }
  return null;
}

function runOptimization(p, scenarioKey, algoKey){
  // Defensive: async UI flows may call this before parcels are fully
  // hydrated. Make sure we never crash the whole UI.
  if(!p){
    return {
      scenarioKey,
      algoKey,
      currentRows: [],
      currentTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      bestRows: [],
      bestTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      note: 'parcel undefined'
    };
  }

  // Guarantee a baseline crop breakdown exists.
  ensureBaselineCropCurrent(p);

  if(!Array.isArray(p.cropCurrent)) p.cropCurrent = [];
  if(!p.cropCurrent.length){
    // Still nothing: return a safe empty result.
    return {
      scenarioKey,
      algoKey,
      currentRows: [],
      currentTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      bestRows: [],
      bestTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      note: 'cropCurrent missing'
    };
  }

  const currentRows = p.cropCurrent.map(c=>{
    const key = c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText);
    const baseWater = safeNum(c._baseWaterPerDa, safeNum(c.waterPerDa, 0));
    const grossWater = safeNum(c._officialGrossWaterPerDa, deliveredWaterPerDa(baseWater, key));
    const area = safeNum(c.area, 0);
    return ({
    name: c.name,
    area: c.area,
    season: c.season || 'â€”',
    irrigationCurrentKey: c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText),
    irrigationCurrentText: c.irrigationCurrentText || 'â€”',
    // tabloda gÃ¶sterilecek su: yÃ¶nteme gÃ¶re teslim edilen (gross) su
    waterPerDa: deliveredWaterPerDa(c.waterPerDa, c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText)),
    profitPerDa: c.profitPerDa,
    totalWater: c.area*deliveredWaterPerDa(c.waterPerDa, c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText)),
    _baseWaterPerDa: baseWater,
    waterPerDa: grossWater,
    totalWater: area * grossWater,
    totalProfit: c.area*c.profitPerDa
  });
  });
  const currentTotals = sumMetrics(currentRows);

  // BahÃ§e / Ã§ok yÄ±llÄ±k parsellerde ANA ÃœRÃœN KORUNUR.
  // KullanÄ±cÄ± S1 veya S2 seÃ§se bile mevcut meyve aÄŸacÄ± / baÄŸ / Ã§ok yÄ±llÄ±k Ã¼rÃ¼n sÃ¶kÃ¼lÃ¼p
  // yerine yeni bir ana ticari Ã¼rÃ¼n Ã¶nerilmez. Ä°yileÅŸtirme; sulama yÃ¶ntemi, kÄ±sÄ±ntÄ± dÃ¼zeyi,
  // sulama zamanÄ± ve sÄ±ra arasÄ± Ã¶rtÃ¼/yeÅŸil gÃ¼bre bitkisi Ã¼zerinden yapÄ±lÄ±r.
  const seasonSource = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';
  const declaredCurrent = p?.current_crop || p?.currentCrop || p?.crop || null;
  let domName = null;
  let bestCurrent = null;
  for(const r of (currentRows||[])){
    if(!bestCurrent || safeNum(r.area) > safeNum(bestCurrent.area)) bestCurrent = r;
  }
  if(declaredCurrent && isPerennialCropName(declaredCurrent)){
    domName = declaredCurrent;
  }else if(bestCurrent && bestCurrent.name){
    domName = bestCurrent.name;
  }else{
    domName = dominantCropNameForParcel(p) || declaredCurrent || null;
  }
  const orchardLocked = !!(p?.parcel_type === 'orchard' || p?.is_orchard || p?.cok_yillik_kilit === 'Evet' || (domName && isPerennialCropName(domName)));
  if(orchardLocked && domName && scenarioKey !== 'mevcut'){
    const adj = s2IrrigationAdjust(scenarioKey);
    const orchardAlternatives = orchardInterrowAlternativesForMain(domName);
    const currentMain = (currentRows || []).find(r=>normCropName(r.name) === normCropName(domName)) || bestCurrent || currentRows[0] || null;
    const currentKey = currentMain?.irrigationCurrentKey || irrKeyFromText(currentMain?.irrigationCurrentText || '') || 'drip';
    const suggestedKey = irrigationKeysForCrop(domName).suggestedKey || currentKey;
    const baseNet = safeNum(currentMain?.waterPerDa, 0) * Math.max(0.35, IRR_EFF[currentKey] || STATE.irrigEfficiency || 0.62);
    const area = +(safeNum(p?.area_da, currentMain?.area || 0)).toFixed(1);
    const waterPerDa = deliveredWaterPerDa(baseNet * adj.wmul, suggestedKey);
    const profitPerDa = +(safeNum(currentMain?.profitPerDa, 0) * adj.pmul).toFixed(2);
    const rows = [{
      name: domName,
      area,
      season: currentMain?.season || 'Ã‡ok yÄ±llÄ±k',
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: currentMain?.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: +(baseNet * adj.wmul).toFixed(3),
      waterPerDa: +waterPerDa.toFixed(3),
      profitPerDa,
      totalWater: +(area * waterPerDa).toFixed(2),
      totalProfit: +(area * profitPerDa).toFixed(2),
      orchardLocked: true,
    }];
    const totals = sumMetrics(rows);
    const orchardAlternativeMetrics = orchardAlternativeScenarioMetrics(domName, safeNum(p?.area_da, area), scenarioKey, rows[0], orchardAlternatives);
    const waterSaving = safeNum(currentTotals.water) - safeNum(totals.water);
    return {
      rows,
      totals,
      cropsUsed: [domName],
      irrigationPlan: adj.label,
      lockedCrop: domName,
      orchardKeepMainCrop: true,
      orchardAlternative: orchardAlternatives[0] || null,
      orchardAlternatives,
      orchardAlternativeMetrics,
      waterSavingM3: Math.round(waterSaving),
      profitDeltaTL: Math.round(safeNum(totals.profit) - safeNum(currentTotals.profit))
    };
  }

  if(scenarioKey === "mevcut"){
    return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals };
  }

  // --- v54: Maksimum 2 Ã¼rÃ¼nlÃ¼ ayrÄ±k arama (1. Ã¼rÃ¼n + (uygunsa) 2. Ã¼rÃ¼n) ---
  // AmaÃ§: suyu azaltÄ±rken Ã§iftÃ§inin kÃ¢rÄ±nÄ± korumak (alt sÄ±nÄ±r: mevcut kÃ¢rÄ±n %90'Ä±)
  const profitMin = currentTotals.profit * 0.90;
  const parcelCandidatePool = (typeof getCandidateCropsForParcel === 'function')
    ? getCandidateCropsForParcel(p).filter(c=>c && c.parcelSpecific && normCropName(c.name) !== 'NADAS')
    : [];
  const parcelCandidateByName = new Map();
  for(const c of parcelCandidatePool){
    const k = normCropName(c.name);
    if(k && !parcelCandidateByName.has(k)) parcelCandidateByName.set(k, c);
  }
  const grossCandidateToBaseWater = (name, grossWaterPerDa)=>{
    const keys = irrigationKeysForCrop(name || '');
    const recKey = recommendedIrrKeyForCrop(name || '', keys.currentKey || 'sprinkler') || keys.suggestedKey || keys.currentKey || 'sprinkler';
    const gross = safeNum(grossWaterPerDa, 0);
    if(recKey === 'rainfed') return gross / 0.20;
    return gross * Math.max(0.35, IRR_EFF[recKey] || STATE.irrigEfficiency || 0.62);
  };

  // Robust crop meta lookup:
  // Some sources use underscores (NOHUT_KURU) while catalog keys use spaces/parentheses.
  // If we fail here, recommended rows show 0 water/profit and look "empty".
  function cropMeta(name){
    const cat = STATE.cropCatalog || {};
    const raw = String(name||'').trim();
    const variants = [];
    if(raw) variants.push(raw);
    if(raw && raw.includes('_')) variants.push(raw.replace(/_/g,' '));
    const pretty = prettyCropName(raw);
    if(pretty && pretty !== raw) variants.push(pretty);
    if(pretty && pretty.includes('_')) variants.push(pretty.replace(/_/g,' '));

    for(const v of variants){
      const local = parcelCandidateByName.get(normCropName(v));
      if(local){
        return {
          waterNet: grossCandidateToBaseWater(local.name || v, local.waterPerDa),
          profit: safeNum(local.profitPerDa, 0)
        };
      }
    }

    // Try several normalized keys (uppercased, diacritics-stripped).
    for(const v of variants){
      const k = normCropName(v);
      if(cat[k]){
        let wNet = safeNum(cat[k].waterPerDa);
        let pr = safeNum(cat[k].profitPerDa);
        // If water is missing/zero, try season-derived net water (year-specific)
        if(!(isFinite(wNet) && wNet>0)){
          const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, k);
          if(isFinite(ws) && ws>0) wNet = ws;
        }
        return { waterNet: wNet, profit: pr };
      }
    }
    // Last resort: scan for close match by space/underscore normalization.
    const target = normCropName(raw).replace(/_/g,' ');
    for(const k in cat){
      if(normCropName(k).replace(/_/g,' ') === target){
        let wNet = safeNum(cat[k].waterPerDa);
        let pr = safeNum(cat[k].profitPerDa);
        if(!(isFinite(wNet) && wNet>0)){
          const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, normCropName(k));
          if(isFinite(ws) && ws>0) wNet = ws;
        }
        return { waterNet: wNet, profit: pr };
      }
    }
    return { waterNet: 0, profit: 0 };
  }

  function buildPlanRows(c1, c2){
    const A = safeNum(p.area_da);
    const pair = pairingForCrop(c1) || {season1:'â€”', irr1:'â€”', secondary:'â€”', season2:'â€”', irr2:'â€”'};
    const c2Resolved = (seasonSource === 's1') ? null : (c2 || null);
    const inferredS1 = inferSeasonFromCropName(c1) || 'â€”';
    const inferredS2 = c2Resolved ? (inferSeasonFromCropName(c2Resolved) || 'â€”') : 'â€”';
    const s1 = (seasonSource === 's2') ? inferredS1 : (pair.season1 || inferredS1 || 'â€”');
    const s2 = (seasonSource === 's2') ? inferredS2 : (pair.season2 || inferredS2 || 'â€”');

    // --- Alan kuralÄ± ---
    // EÄŸer 1. ve 2. Ã¼rÃ¼n farklÄ± sezonlardaysa (rotasyon), aynÄ± parsel alanÄ±nda ardÄ±ÅŸÄ±k ekilir.
    // Bu durumda HER sezonun alan toplamÄ± parsel alanÄ±na eÅŸit olmalÄ±; alanÄ± 70/30 bÃ¶lmeyiz.
    // EÄŸer aynÄ± sezon (veya belirsiz) ise, Ã§eÅŸitlendirme varsayÄ±mÄ± ile 70/30 bÃ¶lÃ¼nmÃ¼ÅŸ alan kullanÄ±labilir.
    const isRotation = c2Resolved && (String(s1).toLowerCase() !== String(s2).toLowerCase()) && s1 !== 'â€”' && s2 !== 'â€”';
    let a1, a2;
    if (seasonSource === 's1') {
      a1 = +A.toFixed(1);
      a2 = 0;
    } else if (isRotation) {
      a1 = +A.toFixed(1);
      a2 = +A.toFixed(1);
    } else {
      // 0.1 da hassasiyet: tabloda gÃ¶sterilen alan ile toplamlarÄ±n tutarlÄ± kalmasÄ± iÃ§in alanÄ± burada da yuvarlÄ±yoruz.
      const a1Raw = A * 0.7;
      const a2Raw = Math.max(0, A - a1Raw);
      a1 = +a1Raw.toFixed(1);
      a2 = +a2Raw.toFixed(1);
      // Yuvarlama sonrasÄ± kÃ¼Ã§Ã¼k sapmalar olursa (Ã¶r. 40.6 yerine 40.5), toplamÄ± tekrar A'ya oturt.
      const sumA = a1 + a2;
      if (A > 0 && sumA > 0 && Math.abs(sumA - A) > 0.05) {
        const k = A / sumA;
        a1 = +(a1 * k).toFixed(1);
        a2 = +(Math.max(0, A - a1)).toFixed(1);
      }
    }

    const m1 = cropMeta(c1);
    const m2 = c2Resolved ? cropMeta(c2Resolved) : {waterNet:0, profit:0};

    const irr1CurKey = irrKeyFromText(pair.irr1);
    const irr2CurKey = c2Resolved ? irrKeyFromText(pair.irr2) : 'rainfed';
    const irr1RecKey = recommendedIrrKeyForCrop(c1, irr1CurKey);
    const irr2RecKey = c2Resolved ? recommendedIrrKeyForCrop(c2Resolved, irr2CurKey) : 'rainfed';

    // Sulama yÃ¼kseltme maliyeti (Ã§ok kaba): damlaya geÃ§iÅŸte da baÅŸÄ±na kÃ¼Ã§Ã¼k yatÄ±rÄ±m bedeli
    const upgradeCostDa = (from,to)=>{
      if(from===to) return 0;
      if(to==='drip') return 250; // damla dÃ¶nÃ¼ÅŸÃ¼m
      if(to==='sprinkler' && from==='surface') return 150;
      return 50;
    };

    const p1 = m1.profit - upgradeCostDa(irr1CurKey, irr1RecKey);
    const p2 = c2Resolved ? (m2.profit - upgradeCostDa(irr2CurKey, irr2RecKey)) : 0;

    const w1 = deliveredWaterPerDa(m1.waterNet, irr1RecKey);
    const w2 = c2Resolved ? deliveredWaterPerDa(m2.waterNet, irr2RecKey) : 0;

    const rows = [];
    rows.push({
      name: prettyCropName(c1),
      season: s1,
      irrigationCurrentKey: irr1CurKey,
      irrigationCurrentText: irrigationLabel(irr1CurKey),
      irrigationSuggestedKey: irr1RecKey,
      irrigationSuggestedText: irrigationLabel(irr1RecKey),
      irrigationSuggested: irrigationLabel(irr1RecKey),
      // Keep NET (field) water requirement so the UI can compute delivered (gross) water
      // consistently based on the shown irrigation method.
      _baseWaterPerDa: safeNum(m1.waterNet, 0),
      area: +a1.toFixed(1),
      waterPerDa: +w1.toFixed(3),
      profitPerDa: +p1.toFixed(3),
      totalWater: a1*w1,
      totalProfit: a1*p1
    });
    if(c2Resolved){
      rows.push({
        name: prettyCropName(c2Resolved),
        season: s2,
        irrigationCurrentKey: irr2CurKey,
        irrigationCurrentText: irrigationLabel(irr2CurKey),
        irrigationSuggestedKey: irr2RecKey,
        irrigationSuggestedText: irrigationLabel(irr2RecKey),
        irrigationSuggested: irrigationLabel(irr2RecKey),
        _baseWaterPerDa: safeNum(m2.waterNet, 0),
        area: +a2.toFixed(1),
        waterPerDa: +w2.toFixed(3),
        profitPerDa: +p2.toFixed(3),
        totalWater: a2*w2,
        totalProfit: a2*p2
      });
    }
    return rows;
  }

  // --- Aday havuzlarÄ± (sezon veri setine gÃ¶re) ---
  // Senaryo-1: 15 ana Ã¼rÃ¼n + geniÅŸ 2. Ã¼rÃ¼n havuzu
  // Senaryo-2: mutabÄ±k kalÄ±nan Ã¼rÃ¼n listesi (meyve + tarla) ve sadece sÄ±nÄ±rlÄ± 2. Ã¼rÃ¼n
  //            (nadas gibi). BÃ¶ylece "Senaryo-2 seÃ§ili ama Ã¼rÃ¼nler deÄŸiÅŸmiyor" sorunu Ã§Ã¶zÃ¼lÃ¼r.
  let primaryCandidates = parcelCandidatePool.length
    ? parcelCandidatePool.map(c=>c.name).filter(c=>normCropName(c) !== "NADAS")
    : S1_PRIMARY_CROPS.slice().filter(c=>normCropName(c) !== "NADAS");
  if(seasonSource === 's1' && inferParcelTypeKey(p) !== 'orchard'){
    primaryCandidates = primaryCandidates.filter(c=>!isPerennialCropName(c));
  }
  if(seasonSource === 's1'){
    // Su verimliliÄŸi hedefinde yalnÄ±z mevcut S1 ana Ã¼rÃ¼n listesine kilitlenmek,
    // baklagil/dÃ¼ÅŸÃ¼k su alternatifleri tabloya girse bile seÃ§ilememesine yol aÃ§Ä±yordu.
    const strategicLowWater = ['NOHUT','MERCIMEK','KIMYON','ISPANAK','MARUL','TURP','LAHANA'];
    primaryCandidates = Array.from(new Set([...primaryCandidates, ...strategicLowWater]))
      .filter(c=>normCropName(c) !== "NADAS");
  }
  let secondaryPool = Array.from(new Set([
    ...S1_SECONDARY_CROPS,
    'BuÄŸday (Dane)','Arpa (Dane)','SilajlÄ±k MÄ±sÄ±r','FiÄŸ (YeÅŸilot)','Yem Bezelyesi',
    'AyÃ§iÃ§eÄŸi','AyÃ§iÃ§eÄŸi (YaÄŸlÄ±k)','Marul','Ispanak','Fasulye (Taze)','Kabak (Ã‡erezlik)'
  ]));
  if(seasonSource === 's2'){
    // S2 mantÄ±ÄŸÄ±:
    // - BahÃ§e / baÄŸ parsellerinde Ã¼rÃ¼n korunur (yukarÄ±da erken dÃ¶nÃ¼ÅŸ var).
    // - Tarla parsellerinde ise yazlÄ±k + kÄ±ÅŸlÄ±k mÃ¼navebe adaylarÄ± denenir.
    primaryCandidates = S2_SUMMER_RAW.slice();
    secondaryPool = S2_WINTER_RAW.slice();

    // Tarla parselinde bahÃ§e Ã¼rÃ¼nÃ¼ Ã¶nerme.
    const lu = landUseCodeFromSoilUnit(p.soil_unit_code || '');
    const allowFruitVine = !!lu;
    if(allowFruitVine){
      // Ã‡ok yÄ±llÄ±k parsel ise zaten yukarÄ±da lock uygulanÄ±yor; burada gÃ¼venli kal.
      primaryCandidates = primaryCandidates.slice();
    }
  }

  // Uyum kuralÄ±: aynÄ± familyadan kaÃ§Ä±n
  const fam = (STATE && STATE.cropFamilyMap) ? STATE.cropFamilyMap : {};
  const sameFam = (a,b)=>{ const fa=fam[prettyCropName(a)]||fam[a]||fam[normCropName(a)]; const fb=fam[prettyCropName(b)]||fam[b]||fam[normCropName(b)]; return fa && fb && fa===fb; };

  const scorePlan = (rows)=>{
    const t = sumMetrics(rows);
    // senaryoya gÃ¶re skor: su tasarruf => su aÄŸÄ±rlÄ±k, max_kar => kÃ¢r aÄŸÄ±rlÄ±k, dengeli => ikisi
    const water = t.water;
    const profit = t.profit;
    if(profit < profitMin) return { ok:false, score: Number.POSITIVE_INFINITY, totals:t };
    const planArea = safeNum(t.area, 0) || safeNum(p.area_da, 0);
    const planBudget = (typeof parcelWaterBudget === 'function') ? parcelWaterBudget(planArea, p) : 0;
    if(planBudget > 0 && water > planBudget + 1e-6){
      return { ok:false, score: Number.POSITIVE_INFINITY, totals:t, reason:'Parsel alan bazlÄ± su kotasÄ±nÄ± aÅŸÄ±yor' };
    }
    let score;
    if(scenarioKey === 'su_tasarruf') score = water - 0.10*profit;
    else if(scenarioKey === 'maks_kar') score = -profit + 0.05*water;
    else score = water - 0.05*profit;
    return { ok:true, score, totals:t };
  };

  let best = null;
  // Su tasarrufu senaryosu iÃ§in ayrÄ±ca "en dÃ¼ÅŸÃ¼k su" adayÄ±nÄ± takip et
  // (kÃ¢r eÅŸiÄŸi saÄŸlansa da saÄŸlanmasa da), bÃ¶ylece su artÄ±ÅŸÄ± gibi
  // Ã§iftÃ§iyi ÅŸaÅŸÄ±rtan sonuÃ§lar engellenir.
  let bestMinWater = null;
  const seed = _hashInt(String(algoKey||'ga')) + _hashInt(p.id||'P');
  for(const c1 of primaryCandidates){
    // Ã–n tanÄ±mlÄ± eÅŸleÅŸme (Senaryo-1 iÃ§in). Senaryo-2'de geniÅŸ eÅŸleÅŸme
    // kurallarÄ±nÄ± kullanmÄ±yoruz; yalnÄ±zca sÄ±nÄ±rlÄ± 2. Ã¼rÃ¼n (Ã¶r. nadas)
    // denenir.
    const defPair = (seasonSource === 's2') ? null : (S1_PAIRING[c1] ? S1_PAIRING[c1].secondary : null);
    const defOpts = [];
    if(defPair && defPair !== 'â€“' && defPair !== '-'){
      if(defPair.includes('/')) defOpts.push(...defPair.split('/').map(x=>x.trim()).filter(Boolean));
      else defOpts.push(defPair);
    }
    const c2Candidates = (seasonSource === 's1')
      ? [null]
      : (seasonSource === 's2'
          ? [...new Set(secondaryPool)].filter(c2=>!c2 || !sameFam(c1,c2))
          : [...new Set([null, ...defOpts, ...secondaryPool])].filter(c2=>!c2 || !sameFam(c1,c2)));

    for(const c2 of c2Candidates){
      const rows = buildPlanRows(c1, c2);
      const res = scorePlan(rows);
      if(!res.ok) continue;
      if(!best || res.score < best.score || (res.score===best.score && ((seed%2)===0))){
        best = { rows, totals: res.totals, score: res.score, c1, c2 };
      }

      // min-water tracker (only meaningful for su_tasarruf)
      if(scenarioKey === 'su_tasarruf'){
        if(!bestMinWater || res.totals.water < bestMinWater.totals.water){
          bestMinWater = { rows, totals: res.totals, score: res.score, c1, c2 };
        }
      }
    }
  }

  if(!best){
    // GÃ¼venli fallback: mevcut desen
    return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals, irrigationPlan: 'Mevcut (kÃ¢r eÅŸiÄŸi saÄŸlanamadÄ±)' };
  }

  // --- Sert su tasarrufu kuralÄ± ---
  // KullanÄ±cÄ± beklentisi: "Su tasarrufu" seÃ§iliyken Ã¶neri, mevcut desenden
  // DAHA FAZLA su tÃ¼ketmemeli. EÄŸer skor en iyisi suyu artÄ±rÄ±yorsa,
  // eldeki adaylar iÃ§indeki en dÃ¼ÅŸÃ¼k su planÄ±na geri dÃ¶n.
  if(scenarioKey === 'su_tasarruf'){
    const curW = safeNum(currentTotals.water, 0);
    const bestW = safeNum(best.totals?.water, 0);
    const minW  = safeNum(bestMinWater?.totals?.water, Number.POSITIVE_INFINITY);

    // 1) Her zaman en dÃ¼ÅŸÃ¼k su planÄ±nÄ± tercih et (kÃ¢r eÅŸiÄŸi saÄŸlandÄ±ktan sonra).
    if(bestMinWater && isFinite(minW) && minW <= bestW){
      best = { ...bestMinWater, note: 'Su tasarrufu: en dÃ¼ÅŸÃ¼k su planÄ± seÃ§ildi' };
    }

    // 2) Su tasarrufu hedefinde su artÄ±ÅŸÄ±na izin verme.
    // EÄŸer en dÃ¼ÅŸÃ¼k su planÄ± bile mevcut desenden fazla su istiyorsa, mevcut deseni koru.
    const finalW = safeNum(best?.totals?.water, 0);
    if(curW > 0 && finalW > curW + 1e-6){
      return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals, irrigationPlan: 'Su tasarrufu: Ã¶neri suyu artÄ±rdÄ±ÄŸÄ± iÃ§in mevcut desen korundu' };
    }

    // 3) Su verimliliÄŸi hedefinde yalnÄ±z toplam kÃ¢ra bakma; Ã§iftÃ§iye su baÅŸÄ±na
    // en yÃ¼ksek ekonomik etkiyi veren alternatifi de Ã¶ne Ã§Ä±kar. Bu, Ã¶rneÄŸin
    // NOHUT gibi Ã§ok dÃ¼ÅŸÃ¼k suyla yeterli kÃ¢r Ã¼reten Ã¼rÃ¼nlerin TURP/LAHANA gibi
    // daha yÃ¼ksek toplam kÃ¢rlÄ± ama daha fazla su isteyen Ã¼rÃ¼nlerin arkasÄ±nda
    // kaybolmasÄ±nÄ± engeller.
    try{
      const altEff = (typeof _alternativeCandidatesForParcel === 'function')
        ? _alternativeCandidatesForParcel(p, best.rows)
            .filter(a=>safeNum(a.water,0) > 0)
            .filter(a=>safeNum(a.profit,0) >= profitMin)
            .filter(a=>safeNum(a.water,0) <= Math.min(curW || Infinity, safeNum(best.totals?.water, Infinity)) + 1e-6)
            .sort((a,b)=>(safeNum(b.eff,0)-safeNum(a.eff,0)) || (safeNum(a.water,0)-safeNum(b.water,0)))[0]
        : null;
      const bestEff = safeNum(best.totals?.profit,0) / Math.max(1, safeNum(best.totals?.water,0));
      if(altEff && safeNum(altEff.eff,0) > bestEff + 0.01){
        const area = safeNum(p.area_da, 0);
        const waterPerDa = safeNum(altEff.water,0) / Math.max(1, area);
        const profitPerDa = safeNum(altEff.profit,0) / Math.max(1, area);
        const suggestedKey = irrigationKeysForCrop(altEff.crop).suggestedKey || 'sprinkler';
        const eff = Math.max(0.35, IRR_EFF[suggestedKey] || STATE.irrigEfficiency || 0.62);
        const rows = [{
          name: prettyCropName(altEff.crop),
          season: inferSeasonFromCropName(altEff.crop) || 'Ana Ã¼rÃ¼n',
          area: +area.toFixed(1),
          irrigationSuggestedKey: suggestedKey,
          irrigationSuggestedText: irrigationLabel(suggestedKey),
          irrigationSuggested: irrigationLabel(suggestedKey),
          _baseWaterPerDa: +(waterPerDa * eff).toFixed(3),
          waterPerDa: +waterPerDa.toFixed(3),
          profitPerDa: +profitPerDa.toFixed(3),
          totalWater: safeNum(altEff.water,0),
          totalProfit: safeNum(altEff.profit,0),
        }];
        best = { rows, totals: sumMetrics(rows), c1: altEff.crop, c2: null, note: 'Su verimliliÄŸi: en yÃ¼ksek TL/mÂ³ alternatifi seÃ§ildi' };
      }
    }catch(_e){}
  }

  const irrigationPlan = 'Sulama Ã¶nerisi: ' + best.rows.map(r=>`${r.name} â†’ ${r.irrigationSuggested}`).join(' | ');
  return { rows: best.rows, totals: best.totals, cropsUsed: [best.c1, best.c2].filter(Boolean), irrigationPlan };
}

function getOptimizationResult(parcelId, scenarioKey, algoKey){
  optimizationCache[parcelId] ??= {};
  optimizationCache[parcelId][scenarioKey] ??= {};
  if(!optimizationCache[parcelId][scenarioKey][algoKey]){
    const p = parcelData.find(x=>x.id===parcelId);
    optimizationCache[parcelId][scenarioKey][algoKey] = runOptimization(p, scenarioKey, algoKey);
  }
  return optimizationCache[parcelId][scenarioKey][algoKey];
}


function computeCropData(p, scenarioKey, algoKey) {
  // Mevcut desen: her zaman runOptimization iÃ§indeki su/da (sulama randÄ±manÄ± dahil) ile hesapla
  const curRes = runOptimization(p, 'mevcut', algoKey);
  const current = (curRes.rows || []).map(r=>({ ...r, irrigationSuggested: undefined }));
  const currentTotals = sumMetrics(current);
  const dominantCurrent = Array.isArray(current) && current.length
    ? [...current].sort((a,b)=>safeNum(b.area,0)-safeNum(a.area,0))[0]
    : null;
  const isPlaceholderCropName = (name)=>{
    const raw = String(name||'').trim();
    const nk = normCropName(raw).replace(/[^A-ZÃ‡ÄÄ°Ã–ÅÃœ0-9]/g,'');
    return !raw || raw === 'â€”' || raw === '-' || raw === 'null' || raw === 'undefined' || ['URUN','ÃœRÃœN','NA','N/A'].includes(nk);
  };
  const currentRowForName = (name)=>{
    const nn = normCropName(name||'');
    return (current||[]).find(x=>normCropName(x.name||'') === nn) || dominantCurrent || null;
  };

  // Referans gÃ¶rÃ¼nÃ¼mÃ¼nde saÄŸdaki tablo/Ã¶zet mevcut deseni aynen yansÄ±tmalÄ±.
  // Bu modda optimizasyon sonucu, placeholder Ã¼rÃ¼n adÄ± veya farklÄ± sulama etiketi gÃ¶sterilmez.
  if(String(scenarioKey||'').trim().toLowerCase() === 'mevcut'){
    const rec = (current || []).map(r=>({
      ...r,
      irrigationSuggestedKey: r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText),
      irrigationSuggestedText: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText)),
      irrigationSuggested: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText)),
    }));
    return {
      current,
      currentTotals,
      rec,
      recTotals: {
        water: currentTotals.water,
        profit: currentTotals.profit,
        water_eff: currentTotals.water > 0 ? (currentTotals.profit / currentTotals.water) : 0,
        water_current_irrig: currentTotals.water,
        water_saving_m3: 0,
        water_saving_pct: 0,
      },
      recMeta: { referenceMode: true, irrigationPlan: 'Referans gÃ¶rÃ¼nÃ¼m: mevcut Ã¼rÃ¼n ve mevcut sulama yÃ¶ntemi aynen gÃ¶sterilir.' },
    };
  }

  // Ã–nerilen: kÃ¼resel su bÃ¼tÃ§esi uygulanmÄ±ÅŸ havza planÄ±ndan Ã§ek
  const basin = computeBasinPlan(scenarioKey, algoKey);
  const opt = basin.plan[p.id] || getOptimizationResult(p.id, scenarioKey, algoKey);

  const recommended = (opt.rows || []).map((r) => {
    const fallbackCurrent = currentRowForName(r.name);
    const rawName = isPlaceholderCropName(r.name)
      ? (fallbackCurrent?.name || p?.current_crop || p?.currentCrop || p?.crop || 'â€”')
      : String(r.name||'').trim();
    const name = rawName;
    const area = safeNum(r.area, safeNum(fallbackCurrent?.area, 0));
    // Some producers already store delivered (gross) water in r.waterPerDa.
    // Prefer explicit NET base water if available to avoid double-adjusting.
    const hasExplicitBase = r._baseWaterPerDa != null || r.baseWaterPerDa != null;
    const grossFromTotal = area > 0 && Number.isFinite(safeNum(r.totalWater, NaN)) ? (safeNum(r.totalWater, 0) / area) : NaN;
    const baseWaterPerDa = hasExplicitBase
      ? safeNum((r._baseWaterPerDa ?? r.baseWaterPerDa), safeNum(fallbackCurrent?._baseWaterPerDa ?? fallbackCurrent?.waterPerDa, 0))
      : safeNum(r.waterPerDa, safeNum(grossFromTotal, safeNum(fallbackCurrent?.waterPerDa, 0)));
    const profitPerDa = safeNum(r.profitPerDa, safeNum(fallbackCurrent?.profitPerDa, 0));
    const fallbackCurrentKey = fallbackCurrent?.irrigationCurrentKey || irrKeyFromText(fallbackCurrent?.irrigationCurrentText || '');
    const keyBlock = irrigationKeysForCrop(name);
    const currentKey = r.irrigationCurrentKey || r.irrigationCurrent || fallbackCurrentKey || keyBlock.currentKey;
    const suggestedKey = r.irrigationSuggestedKey || r.irrigationRecommended || keyBlock.suggestedKey || currentKey;
    const cropKey = (_normIrrLookupKeys(name)[1] || String(name||''));

    // UI shows gross water (m3/da). Rows with explicit base store net field water;
    // legacy/cached rows without it are already gross and must not be adjusted twice.
    const waterPerDa = hasExplicitBase
      ? deliveredWaterPerDa(baseWaterPerDa, suggestedKey)
      : safeNum(grossFromTotal, baseWaterPerDa);
    const totalWater = area * waterPerDa;
    const totalProfit = area * profitPerDa;

    // Season may be missing for some sources.
    let season = (String(r.season||'').trim() || String(fallbackCurrent?.season||'').trim() || 'â€”');
    if(!season || season === 'â€”'){
      const pair = pairingForCrop(name);
      if(pair && pair.season1) season = pair.season1;
      if((!season || season === 'â€”')){
        const nn = normCropName(name).replace(/_/g,' ');
        if(nn.includes('NOHUT')) season = 'YazlÄ±k';
        else if(nn.includes('BUGDAY') || nn.includes('ARPA') || nn.includes('CAVDAR')) season = 'KÄ±ÅŸlÄ±k';
      }
    }

    return {
      name,
      area,
      season,
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: fallbackCurrent?.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: hasExplicitBase ? baseWaterPerDa : safeNum(baseWaterPerDa * Math.max(0.35, IRR_EFF[suggestedKey] || STATE.irrigEfficiency || 0.62), baseWaterPerDa),
      waterPerDa,
      profitPerDa,
      totalWater,
      totalProfit,
      _cropKey: cropKey,
    };
  });

  // Ã‡ok yÄ±llÄ±k/bahÃ§e parsellerinde ana Ã¼rÃ¼n ekranda hiÃ§bir koÅŸulda tarla Ã¼rÃ¼nÃ¼yle yer deÄŸiÅŸtirmemeli.
  // Ã–zellikle tarayÄ±cÄ±da eski yerel dÃ¼zeltme kayÄ±tlarÄ± kaldÄ±ÄŸÄ±nda "mevcut=KayÄ±sÄ±, Ã¶neri=Mercimek"
  // gibi Ã§eliÅŸkili gÃ¶rÃ¼nÃ¼m oluÅŸabiliyordu. Bu blok, UI tarafÄ±nda tek kaynaktan tutarlÄ± sonuÃ§ Ã¼retir.
  const orchardMainCurrent = (dominantCurrent && isPerennialCropName(dominantCurrent.name)) ? dominantCurrent : null;
  const orchardForcedUi = !!(p?.parcel_type === 'orchard' || p?.is_orchard || orchardMainCurrent);
  let recommendedForUi = recommended;
  if(orchardForcedUi && orchardMainCurrent){
    const adj = s2IrrigationAdjust(scenarioKey);
    const currentKey = orchardMainCurrent.irrigationCurrentKey || irrKeyFromText(orchardMainCurrent.irrigationCurrentText || '') || 'drip';
    const suggestedKey = irrigationKeysForCrop(orchardMainCurrent.name).suggestedKey || currentKey;
    const baseNet = isFinite(safeNum(orchardMainCurrent._baseWaterPerDa, NaN))
      ? safeNum(orchardMainCurrent._baseWaterPerDa, 0)
      : safeNum(orchardMainCurrent.waterPerDa, 0) * Math.max(0.35, IRR_EFF[currentKey] || STATE.irrigEfficiency || 0.62);
    const forcedArea = +(safeNum(p?.area_da, orchardMainCurrent.area || 0)).toFixed(1);
    const forcedBaseNet = +(baseNet * adj.wmul).toFixed(3);
    const forcedWaterPerDa = deliveredWaterPerDa(forcedBaseNet, suggestedKey);
    const forcedProfitPerDa = +(safeNum(orchardMainCurrent.profitPerDa, 0) * adj.pmul).toFixed(2);
    recommendedForUi = [{
      name: orchardMainCurrent.name,
      area: forcedArea,
      season: orchardMainCurrent.season || 'BahÃ§e (Ã§ok yÄ±llÄ±k)',
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: orchardMainCurrent.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: forcedBaseNet,
      waterPerDa: +forcedWaterPerDa.toFixed(3),
      profitPerDa: forcedProfitPerDa,
      totalWater: +(forcedArea * forcedWaterPerDa).toFixed(2),
      totalProfit: +(forcedArea * forcedProfitPerDa).toFixed(2),
      _cropKey: (_normIrrLookupKeys(orchardMainCurrent.name)[1] || String(orchardMainCurrent.name||'')),
      orchardLocked: true,
    }];
    const orchardAltMetrics = orchardAlternativeScenarioMetrics(orchardMainCurrent.name, safeNum(p?.area_da, forcedArea), scenarioKey, recommendedForUi[0], null);
    opt.orchardAlternativeMetrics = orchardAltMetrics;
    opt.orchardAlternatives = orchardAltMetrics;
  }

  const recTotalsAdj = sumMetrics(recommendedForUi);
  const recWaterCurrentIrr = recommendedForUi.reduce((acc, rr) => {
    const w = deliveredWaterPerDa(safeNum(rr._baseWaterPerDa, rr.waterPerDa), rr.irrigationCurrentKey);
    return acc + safeNum(rr.area,0) * w;
  }, 0);

  return {
    current,
    currentTotals,
    rec: recommendedForUi,
    recTotals: {
      water: recTotalsAdj.water,
      profit: recTotalsAdj.profit,
      water_eff: recTotalsAdj.water > 0 ? (recTotalsAdj.profit / recTotalsAdj.water) : 0,
      water_current_irrig: recWaterCurrentIrr,
      water_saving_m3: Math.max(0, recWaterCurrentIrr - recTotalsAdj.water),
      water_saving_pct: recWaterCurrentIrr > 0 ? (Math.max(0, recWaterCurrentIrr - recTotalsAdj.water) / recWaterCurrentIrr) : 0,
    },
    recMeta: { irrigationPlan: opt.irrigationPlan || null, lockedCrop: opt.lockedCrop || null, orchardKeepMainCrop: !!opt.orchardKeepMainCrop, orchardAlternative: opt.orchardAlternative || null, orchardAlternatives: Array.isArray(opt.orchardAlternatives) ? opt.orchardAlternatives : null, orchardAlternativeMetrics: Array.isArray(opt.orchardAlternativeMetrics) ? opt.orchardAlternativeMetrics : null, alternativePatterns: buildUiAlternativePatterns(p, current, recommendedForUi, { orchardKeepMainCrop: !!opt.orchardKeepMainCrop, orchardAlternative: opt.orchardAlternative || null, orchardAlternatives: Array.isArray(opt.orchardAlternatives) ? opt.orchardAlternatives : null, orchardAlternativeMetrics: Array.isArray(opt.orchardAlternativeMetrics) ? opt.orchardAlternativeMetrics : null }, scenarioKey) },
  };
}


