function cropGrowthDays(cropName, season=''){
  const n = normCropName(cropName);
  const rule = (STATE.backendMeta?.s1_crop_rules || {})[cropName] || (STATE.backendMeta?.s1_crop_rules || {})[prettyCropName(cropName)] || null;
  const d = safeNum(rule?.growth_days || rule?.days, NaN);
  if(Number.isFinite(d) && d > 0) return Math.round(d);
  if(n.includes('BUGDAY') || n.includes('ARPA') || n.includes('CAVDAR') || n.includes('TRITIKALE')) return 150;
  if(n.includes('LAHANA')) return 120;
  if(n.includes('DOMATES') || n.includes('BIBER')) return 120;
  if(n.includes('MERCIMEK') || n.includes('NOHUT')) return 110;
  if(n.includes('MARUL') || n.includes('ISPANAK') || n.includes('TURP')) return 60;
  return 100;
}

