function ensureCropDetailModalV94(){
  let modal = document.getElementById('cropDetailModalV94');
  if(modal) return modal;
  modal = document.createElement('div');
  modal.id = 'cropDetailModalV94';
  modal.className = 'crop-modal-v94';
  modal.innerHTML = `<div class="crop-modal-backdrop" data-crop-modal-close="1"></div><section class="crop-modal-panel"><button type="button" class="crop-modal-close" data-crop-modal-close="1">Kapat</button><div id="cropDetailModalBodyV94"></div></section>`;
  document.body.appendChild(modal);
  modal.addEventListener('click', (ev)=>{ if(ev.target?.dataset?.cropModalClose){ modal.classList.remove('is-open'); } });
  document.addEventListener('keydown', (ev)=>{ if(ev.key === 'Escape') modal.classList.remove('is-open'); });
  return modal;
}

function openCropDetailModalV94(index){
  const rows = Array.isArray(STATE.lastProductDetailRows) ? STATE.lastProductDetailRows : [];
  const row = rows[index] || rows[0];
  if(!row) return;
  const modal = ensureCropDetailModalV94();
  const body = document.getElementById('cropDetailModalBodyV94');
  if(body) body.innerHTML = cropFullInfoHtmlV94(row, index);
  modal.classList.add('is-open');
}

// SeÃ§ili parsel iÃ§in "Ã¶nerilen Ã¼rÃ¼n" ÅŸeridini gÃ¼ncelle (grafik yerine)
function updateProductCards(){
  const box = document.getElementById('productCards');
  if(!box) return;

  const p = parcelData.find((x) => x.id === selectedParcelId);
  const { current, rec, recMeta } = computeCropData(p, selectedScenario, selectedAlgo);
  try{ STATE.lastRecMeta = recMeta || null; }catch(_e){}

  // "Mevcut" seÃ§iliyse -> mevcut; diÄŸerlerinde optimizasyon Ã§alÄ±ÅŸmadÄ±ysa -> mevcut
  const canShowOpt = (selectedScenario === 'mevcut') || canShowOptimizedForCurrentSelection();
  let rows = (selectedScenario === 'mevcut') ? current : (canShowOpt ? rec : current);
  if(!Array.isArray(rows) || rows.length === 0) rows = current;

  const orchardLockedUi = !!(p?.parcel_type === 'orchard' || p?.is_orchard || (current && current[0] && isPerennialCropName(current[0].name)));
  const orchardAlternativeUi = orchardLockedUi ? orchardAlternativeFallback(current, rec, STATE.lastRecMeta || null) : null;
  const topRows = [...rows]
    .filter(r => safeNum(r.area,0) > 0)
    .sort((a,b)=> safeNum(b.area,0) - safeNum(a.area,0))
    .slice(0, 6);
  STATE.lastProductDetailRows = topRows;

  if(!topRows.length){
    box.innerHTML = `<div class="product-empty">ÃœrÃ¼n Ã¶nerisi henÃ¼z oluÅŸmadÄ±. Optimizasyonu Ã§alÄ±ÅŸtÄ±rÄ±n.</div>`;
    return;
  }

  const emojiFor = (name)=>{
    const n = String(name||'').toLowerCase();
    if(n.includes('bugday') || n.includes('arpa') || n.includes('cavdar')) return 'ğŸŒ¾';
    if(n.includes('misir')) return 'ğŸŒ½';
    if(n.includes('patates')) return 'ğŸ¥”';
    if(n.includes('sogan')) return 'ğŸ§…';
    if(n.includes('nohut') || n.includes('mercimek') || n.includes('fasulye') || n.includes('fiy')) return 'ğŸ«˜';
    if(n.includes('aycicegi')) return 'ğŸŒ»';
    if(n.includes('kabak')) return 'ğŸƒ';
    if(n.includes('pancar')) return 'ğŸ ';
    if(n.includes('marul') || n.includes('ispanak') || n.includes('lahana')) return 'ğŸ¥¬';
    if(n.includes('biber')) return 'ğŸŒ¶ï¸';
    if(n.includes('turp')) return 'ğŸ¥•';
    if(n.includes('bag') || n.includes('uzum')) return 'ğŸ‡';
    if(n.includes('yonca') || n.includes('fig')) return 'ğŸŒ¿';
    if(n.includes('nadas')) return 'ğŸŸ«';
    return 'ğŸŒ±';
  };

  const pillRows = orchardLockedUi && current && current.length ? current.slice(0,1) : topRows;
  const pills = pillRows.map((r, idx)=>{
    const name = escapeHtml(r.name);
    const season = escapeHtml(r.season || '');
    const label = season && season !== 'â€”' ? `${name} <span class="pill-season">${season}</span>` : name;
    const sep = (idx < pillRows.length-1) ? `<span class="crop-sep">/</span>` : '';
    return `<span class="crop-pill"><span class="crop-emoji">${emojiFor(r.name)}</span><span class="pill-name">${label}</span></span>${sep}`;
  }).join('');

  const orchardAlternativesCompact = orchardLockedUi ? orchardAlternativeListFallback(current, rec, STATE.lastRecMeta || null).slice(0,4).map(x=>prettyCropName(x.name)).join(', ') : '';
  const orchardMainNameUi = prettyCropName(current[0]?.name || topRows[0]?.name || '');
  const altPatternCompact = (()=>{ const list = Array.isArray(STATE.lastRecMeta?.alternativePatterns) ? STATE.lastRecMeta.alternativePatterns.slice(0,3).map(x=>x.patternName).join(' â€¢ ') : ''; return list; })();
  const orchardNote = orchardLockedUi ? `<div class="crop-note"><strong>Ana Ã¼rÃ¼n korunur:</strong> ${escapeHtml(orchardMainNameUi)}. ${orchardAlternativesCompact ? `Alt / sÄ±ra arasÄ± alternatifler: ${escapeHtml(orchardAlternativesCompact)}.` : 'ÃœrÃ¼n sÃ¶kÃ¼lÃ¼p yerine baÅŸka ana Ã¼rÃ¼n Ã¶nerilmez.'}${altPatternCompact ? ` <span class="muted">Ä°lk alternatifler: ${escapeHtml(altPatternCompact)}.</span>` : ''}</div>` : `<div class="crop-note">${_seasonModeKey()==='s2' ? 'Ã‡ift Ã¼rÃ¼n / desen bazlÄ± senaryoda ana Ã¶neri ve diÄŸer alternatifler birlikte deÄŸerlendirilir.' : 'Tek Ã¼rÃ¼nlÃ¼ senaryoda en iyi ana Ã¶neri ve diÄŸer gÃ¼Ã§lÃ¼ alternatifler listelenir.'}${altPatternCompact ? ` <span class="muted">Ä°lk alternatifler: ${escapeHtml(altPatternCompact)}.</span>` : ''}</div>`;
  box.innerHTML = `
    <div class="crop-strip">${pills}</div>
    ${orchardNote}
    <div class="crop-detail-list">${topRows.slice(0,3).map((r,i)=>cropInfoCardHtmlV93(r,i)).join('')}</div>
  `;
  box.querySelectorAll('.crop-detail-open').forEach(btn=>{
    btn.addEventListener('click', ()=> openCropDetailModalV94(Number(btn.dataset.cropDetailIndex || 0)));
  });
}

// Leaflet haritasÄ±
let map;
let parcelLayer;
function queueMapResize(delay=180, refit=false){
  setTimeout(()=>{
    try{
      if(!map) return;
      map.invalidateSize(true);
      if(refit && parcelLayer && typeof parcelLayer.getBounds==='function'){
        const b=parcelLayer.getBounds();
        if(b && b.isValid()) map.fitBounds(b.pad(0.18), {animate:false});
      }
    }catch(_e){}
  }, delay);
}

function clearCustomDrawPreview(){
  customDrawPoints = [];
  try{ customDrawMarkers.forEach(m=> map && map.removeLayer(m)); }catch(_e){}
  customDrawMarkers = [];
  try{ if(customDrawShape && map) map.removeLayer(customDrawShape); }catch(_e){}
  customDrawShape = null;
}

function refreshCustomDrawPreview(){
  if(!map) return;
  try{ if(customDrawShape) map.removeLayer(customDrawShape); }catch(_e){}
  if(customDrawPoints.length >= 3){
    customDrawShape = L.polygon(customDrawPoints, {color:'#0b7285', weight:2, dashArray:'6 4', fillColor:'#74c0fc', fillOpacity:0.12, interactive:false}).addTo(map);
    const areaDa = areaDaFromLatLngs(customDrawPoints);
    const areaEl = document.getElementById('manualParcelArea');
    const toggle = document.getElementById('manualAreaOverrideToggle');
    if(areaEl && !(toggle && toggle.checked) && areaDa > 0){
      areaEl.value = areaDa.toFixed(1);
    }
    setUserParcelStatus(`Ã‡izim sÃ¼rÃ¼yor â€¢ otomatik alan: ${formatAreaSummaryText(areaDa)}`);
  }else if(customDrawPoints.length >= 2){
    customDrawShape = L.polyline(customDrawPoints, {color:'#0b7285', weight:2, dashArray:'6 4', interactive:false}).addTo(map);
    setUserParcelStatus(`Ã‡izim sÃ¼rÃ¼yor â€¢ ${customDrawPoints.length} kÃ¶ÅŸe seÃ§ildi`);
  }else{
    customDrawShape = null;
  }
}

function setDrawMode(active){
  customDrawMode = !!active;
  if(!map) return;
  if(active){
    setUserParcelStatus('Ã‡izim modu aÃ§Ä±k');
    if(!customDrawHint){
      customDrawHint = L.control({position:'bottomleft'});
      customDrawHint.onAdd = function(){
        const div = L.DomUtil.create('div', 'draw-help');
        div.innerHTML = 'Ã‡izim modu aÃ§Ä±k: haritaya tÄ±klayarak kÃ¶ÅŸe ekle, sonra <b>Ã‡izimi bitir</b> butonuna bas.';
        return div;
      };
    }
    try{ customDrawHint.addTo(map); }catch(_e){}
  }else{
    try{ if(customDrawHint) customDrawHint.remove(); }catch(_e){}
  }
}

function createOrUpdateCustomParcel(feature, opts={}){
  if(!feature) throw new Error('Parsel geometrisi okunamadÄ±.');
  const latlngs = latLngsFromFeature(feature);
  if(latlngs.length < 3) throw new Error('Polygon iÃ§in en az 3 kÃ¶ÅŸe gerekir.');
  const centroid = centroidOfLatLngs(latlngs);
  const areaDaAuto = areaDaFromLatLngs(latlngs);
  const pid = opts.id || nextUserParcelId();
  const parcel = {
    id: pid,
    name: opts.name || pid,
    display_name: opts.name || pid,
    village: opts.village || '',
    district: opts.district || '',
    area_da: +(safeNum(opts.area_da, areaDaAuto) || 0).toFixed(1),
    lat: +safeNum(opts.lat, centroid.lat).toFixed(6),
    lon: +safeNum(opts.lon, centroid.lng).toFixed(6),
    water_m3: safeNum(opts.water_m3, 0),
    profit_tl: safeNum(opts.profit_tl, 0),
    frontend_custom: true,
    map_only: false,
    current_crop: opts.current_crop || '',
    irrigation_key: opts.irrigation_key || 'sprinkler',
    farmer: opts.farmer || '',
    parcel_type: (opts.parcel_type && opts.parcel_type !== 'auto') ? opts.parcel_type : inferParcelTypeKey(opts.current_crop || feature?.properties?.current_crop || ''),
    source_label: opts.source_label || feature?.properties?.source_label || 'YÃ¼kleme / Ã‡izim',
    owner_username: String(opts.owner_username || feature?.properties?.owner_username || STATE.currentUser?.username || '').trim(),
    approval_status: String(opts.approval_status || feature?.properties?.approval_status || (STATE.currentUser?.role === 'institution' ? 'approved' : 'pending_review')).trim() || 'pending_review',
    approval_note: String(opts.approval_note || feature?.properties?.approval_note || '').trim(),
    reviewed_by: String(opts.reviewed_by || feature?.properties?.reviewed_by || '').trim(),
    reviewed_at: String(opts.reviewed_at || feature?.properties?.reviewed_at || '').trim(),
    submitted_at: String(opts.submitted_at || feature?.properties?.submitted_at || new Date().toISOString()).trim(),
    requested_for_parcel_id: String(opts.requested_for_parcel_id || feature?.properties?.requested_for_parcel_id || '').trim(),
    promoted_to_official: !!(opts.promoted_to_official || feature?.properties?.promoted_to_official),
    soil: opts.soil || { class:'', texture:'', erosion:'' },
    feature: feature,
  };
  const oldIdx = (parcelData||[]).findIndex(p=>String(p.id)===String(pid));
  if(oldIdx >= 0) parcelData.splice(oldIdx, 1, Object.assign(parcelData[oldIdx], parcel));
  else parcelData.push(parcel);

  syncCustomParcelFeatureProperties(parcel);

  if(customUserLayer){
    try{
      const existingLayer = findCustomLayerById(pid);
      if(existingLayer) customUserLayer.removeLayer(existingLayer);
    }catch(_e){}
    customUserLayer.addData(parcel.feature);
    syncCustomParcelLayerBindings(parcel);
  }
  if(STATE.currentUser?.role === 'farmer' && parcel.owner_username){
    attachCustomParcelToUser(parcel.owner_username, pid);
  }
  try{ persistCustomParcels(); }catch(_e){}
  try{ refreshParcelSelect(); }catch(_e){}
  selectedParcelId = pid;
  try{ const sel = document.getElementById('parcelSelect'); if(sel) sel.value = pid; }catch(_e){}
  try{ if(window._focusParcel) window._focusParcel(pid); }catch(_e){}
  updateAreaInputFromGeometry(parcel, true);
  syncUserParcelForm();
  try{ syncOnboardingSection(); }catch(_e){}
  refreshUI();
  return parcel;
}

function parseGeoJsonOrJsonText(txt){
  const obj = JSON.parse(txt);
  if(obj.type === 'FeatureCollection') return (obj.features||[])[0] || null;
  if(obj.type === 'Feature') return obj;
  if(obj.type && obj.coordinates) return { type:'Feature', properties:{}, geometry: obj };
  return null;
}

function parseKmlText(txt){
  const xml = new DOMParser().parseFromString(txt, 'text/xml');
  const coordsNode = xml.querySelector('coordinates');
  if(!coordsNode) return null;
  const coords = coordsNode.textContent.trim().split(/\s+/).map(seg=>seg.split(',').map(Number)).filter(v=>v.length>=2 && isFinite(v[0]) && isFinite(v[1])).map(v=>[v[0], v[1]]);
  if(coords.length < 3) return null;
  const a = coords[0], b = coords[coords.length-1];
  if(a && b && (a[0] !== b[0] || a[1] !== b[1])) coords.push(a);
  return { type:'Feature', properties:{}, geometry:{ type:'Polygon', coordinates:[coords] } };
}

function focusParcelOnAnyLayer(pid){
  try{
    if(!map) return;
    const candidates = [];
    if(parcelLayer) candidates.push(parcelLayer);
    if(customUserLayer) candidates.push(customUserLayer);
    if(window.__PENDING_DRAWING_LAYER) candidates.push(window.__PENDING_DRAWING_LAYER);
    let targetLayer = null;
    candidates.forEach(group=>{
      if(targetLayer || !group || typeof group.eachLayer !== 'function') return;
      group.eachLayer(ly=>{
        const fid = ly?.feature?.properties?.id || ly?.feature?.properties?.name;
        if(String(fid) === String(pid)) targetLayer = ly;
      });
    });
    if(targetLayer){
      const b = targetLayer.getBounds ? targetLayer.getBounds() : null;
      if(b && b.isValid()) map.fitBounds(b.pad(0.35), { animate:true });
      else if(typeof targetLayer.getLatLng === 'function') map.setView(targetLayer.getLatLng(), Math.max(map.getZoom() || 13, 14), { animate:true });
      try{ targetLayer.openPopup(); }catch(_e){}
    }else if(window.__PENDING_MARKERS_BY_ID && window.__PENDING_MARKERS_BY_ID[String(pid)]){
      const marker = window.__PENDING_MARKERS_BY_ID[String(pid)];
      try{ map.setView(marker.getLatLng(), Math.max(map.getZoom() || 13, 14), { animate:true }); marker.openPopup(); }catch(_e){}
    }
  }catch(_e){}
}

