const updateMapLayerStatusV30 = (count, village, pendingCount=0)=>{
  try{
    const box = document.querySelector('.map-tools #mt_layer_status');
    if(!box) return;
    const v = String(village || '').trim();
    const realTotal = Number(count || 0);
    const pendingTotal = Number(pendingCount || 0);
    const total = realTotal + pendingTotal;
    let msg = '';
    let cls = 'ok';
    if(v && total === 0){
      msg = `${v}: gerÃ§ek parsel GeoJSON yok. Haritada yalnÄ±z kÃ¶y sÄ±nÄ±rÄ± gÃ¶sterilir; parsel sÄ±nÄ±rÄ± Ã§izilip kaydedilince burada gÃ¶rÃ¼necek.`;
      cls = 'warn';
    }else if(v && realTotal === 0 && pendingTotal > 0){
      msg = `${v}: ${pendingTotal} parsel kaydÄ± Ã§izim bekliyor. Ä°ÅŸarete tÄ±klayÄ±p sÄ±nÄ±rÄ± Ã§izebilirsiniz.`;
      cls = 'warn';
    }else if(!v){
      msg = `TÃ¼m parseller: ${realTotal} GeoJSON${pendingTotal ? ` + ${pendingTotal} Ã§izim bekleyen kayÄ±t` : ''}`;
    }else{
      msg = `${v}: ${realTotal} parsel GeoJSON${pendingTotal ? ` + ${pendingTotal} Ã§izim bekleyen kayÄ±t` : ''}`;
    }
    box.className = `map-tools-status ${cls}`;
    box.textContent = msg;
  }catch(_e){}
};

const applyMapFilters = ({ village, fit=false } = {})=>{
  if(village !== undefined) activeVillageFilter = String(village || '').trim();
  try{
    const feats = (geojson && geojson.features) ? geojson.features : [];
    const filtered = feats.filter(f=>{
      let v = String(f?.properties?.village || '').trim();
      if(!v) v = villageFromGeoFilenameV22(f?.properties?.source_file || '');
      if(!f.properties) f.properties = {};
      if(v && !f.properties.village) f.properties.village = v;
      if(activeVillageFilter && villageKeyV22(v) !== villageKeyV22(activeVillageFilter)) return false;
      const wm = String(f?.properties?.water_mode || '').toLowerCase();
      if(wm === 'kuru' && !showDryParcels) return false;
      if(wm === 'sulu' && !showIrrigatedParcels) return false;
      if(wm !== 'kuru' && wm !== 'sulu' && !showDryParcels && !showIrrigatedParcels) return false;
      return true;
    });
    const fc = { type: 'FeatureCollection', features: filtered };
    parcelLayer.clearLayers();
    parcelLayer.addData(fc);
    let pendingCount = 0;
    try{ pendingCount = renderPendingDrawingMarkersV33(activeVillageFilter); }catch(_e){ pendingCount = 0; }
    updateMapLayerStatusV30(filtered.length, activeVillageFilter, pendingCount);
    try{ updateStyles(); }catch(_e){}
    refreshVillageBoundary(filtered, activeVillageFilter);
    renderReservoirAreaLayer();
    if(fit){
      let fitted = false;
      if(filtered.length){
        try{ const tmp = L.geoJSON(fc); fitted = fitLayerSafely(tmp); }catch(_e){}
      }
      if(!fitted && villageBoundaryLayer) fitted = fitLayerSafely(villageBoundaryLayer);
      if(!fitted && activeVillageFilter){
        const uploaded = getUploadedVillageBoundary(activeVillageFilter);
        if(uploaded) fitLayerSafely(L.geoJSON(uploaded));
      }
    }
  }catch(_e){}
};

